"use strict";
// ===========================================================================
// "Was ist neu" - kurzer, rein informativer Hinweis beim ersten Login nach
// einem App-Update. Keine Rueckwirkung auf Daten oder Berechnung, komplett
// lokal (localStorage je Geraet, wie dfaSettings/kamSettings).
//
// WIN_CHANGELOG ist eine handverlesene KURZFASSUNG fuer Anwender - nicht der
// volle CHANGELOG_HISTORIE.md-Text (der ist fuer Entwickler gedacht). Bei
// jeder fachlichen Aenderung, die den Versionsstand erhoeht (CLAUDE.md-Regel),
// hier ein bis drei Stichpunkte fuer die neue Version ergaenzen.
// ===========================================================================
const WIN_LETZTE_VERSION="sd_letzteGesehenVersion";
const WIN_CHANGELOG={
 "3.86":["Neues App-Icon.",
  "Zuschnitt: unterschiedliche Blechbreiten können jetzt im selben Rollenabschnitt gemischt werden – spart Verschnitt.",
  "Kamineinfassung: Mass A und D können links/rechts getrennt erfasst werden."],
 "3.87":["Dachfenstereinfassung: Mass A und D können links/rechts getrennt erfasst werden."],
 "3.88":["Kamin- und Dachfenstereinfassung: alle Masse sind durchgehend von A an durchnummeriert, mit aufklappbarer Übersicht samt Beispielskizze."],
 "3.89":["Dachfenstereinfassung: Mass D wird jetzt vom Wandfuss nach oben gemessen, wie am Bau üblich.",
  "Sieben Masse umbenannt, u. a. „Winkel auf Fensterrahmen“ statt „Umschlag vorne“."],
 "3.90":["Dachfenstereinfassung: das überflüssige Mass „Umschlag hinten“ wurde entfernt."],
 "3.91":["Neu: automatische Fortschrittsanzeige „Register X von Y“ in allen Massaufnahme-Registern.",
  "Neu: dieser „Was ist neu“-Hinweis nach einem App-Update."],
 "3.92":["Kamin- und Dachfenstereinfassung: Massbezeichnungen an mehreren Stellen vereinheitlicht, kleinere Formulierungs-Unschärfen dabei behoben."],
 "3.93":["Einfassung rund und Lukarne: aufklappbare Übersicht mit Beispielskizze für alle Masse, wie bei Kamin- und Dachfenstereinfassung."],
 "3.94":["Neu: Register, die schon einmal ausgefüllt wurden, zeigen jetzt einen Haken.",
  "Neu: neue Massaufnahme nach Steildach/Flachdach/Allgemein gruppiert auswählen.",
  "Neu: Projektliste lässt sich jetzt auch nach Massaufnahme-Art filtern.",
  "Kamin- und Dachfenstereinfassung: Massbezeichnungen in den Firmen-Einstellungen und der Hilfe kommen jetzt aus derselben Quelle wie überall sonst.",
  "Regierapport: die hinterlegte Funktion eines Mitarbeiters wird jetzt auch beim nachträglichen Wechsel in der Zeile automatisch übernommen."],
 "3.95":["Regierapport: die Mitarbeiter-Auswahl in der Tabelle zeigt jetzt den vollen Namen statt nur des Kürzels - im gedruckten Rapport steht weiterhin nur das Kürzel.",
  "Regierapport: die Spalten Datum, MA und Funktion in der Tabelle sind breiter, damit der Inhalt vollständig lesbar ist."],
 "3.96":["Systemadministration: Feedback lässt sich jetzt auch für fremde Firmen löschen.",
  "Fehler behoben: verwaiste Dateien im Speicher liessen sich nicht endgültig löschen."],
 "3.97":["Regierapport: das Datumsfeld in der Material-Tabelle ist jetzt breiter und richtig beschriftet."],
 "3.98":["Neu: Lagerverwaltung (Phase 1) - Bestand je Artikel aus dem Materialbestand, geführt über einzelne Buchungen (Zugang/Abgang/Korrektur) statt einer Zahl zum Überschreiben. Sichtbar nur für eigens freigeschaltete Mitarbeitende (Einstellungen → Mitarbeiter → Lager-Zugriff)."],
 "3.99":["Neu: der Betreiber wird jetzt täglich automatisch per E-Mail benachrichtigt, wenn verwaiste Dateien im Speicher gefunden werden - es wird dabei nichts automatisch gelöscht.",
  "Fehler behoben: eine Offerten-PDF oder ein Offerten-Foto konnte fälschlich als „verwaist” gemeldet werden, obwohl sie noch von einer Offerte verwendet wird."],
 "3.100":["Neu: digitale Unterschrift im Regierapport - Auftraggeber und ausführender Mitarbeiter können direkt auf dem Gerät unterschreiben, die Unterschrift erscheint dann im Ausdruck anstelle der leeren Linie.",
  "Ohne digitale Unterschrift bleibt der Ausdruck unverändert - die Linie zum Unterschreiben von Hand steht weiterhin da."],
 "3.101":["Fehler behoben: die Unterschriften-Erfassung wurde im Ausdruck fälschlich doppelt mitgedruckt.",
  "Fehler behoben: der Buchen-Dialog in der Lagerverwaltung öffnete sich hinter den Einstellungen.",
  "Neu: Lagerverwaltung ist jetzt direkt von der Startseite aus erreichbar (mit Lager-Zugriff)."],
 "3.102":["Neu: Material lässt sich in der Lagerverwaltung jetzt per Kamera ein- und ausscannen - ein hinterlegter Barcode öffnet direkt den Buchen-Dialog mit der richtigen Richtung.",
  "Neu: ein Barcode lässt sich im Material-Katalog (Einstellungen → Material) ebenfalls per Kamera hinterlegen.",
  "Die Lagerverwaltung führt jetzt denselben Material-Katalog wie der Regierapport (Schrauben, Dichtband usw.) - der Blech-Materialbestand ist davon unabhängig und bleibt unverändert."],
 "3.103":["Neu: beim Anlegen einer neuen Firma wird das Startpasswort automatisch erzeugt und dem Admin per E-Mail zugeschickt.",
  "Neu: beim Anlegen eines Mitarbeiters lässt sich optional eine E-Mail hinterlegen - sie wird zur zusätzlichen Anmelde-Adresse und die Zugangsdaten werden zugeschickt.",
  "Neu: „Passwort vergessen“ auf dem Anmeldebildschirm - ein Link per E-Mail führt zum Setzen eines neuen Passworts (nur bei hinterlegter E-Mail).",
  "Neu: Systemadministration kann Einladungslinks erzeugen, mit denen jemand selbst eine neue Firma anlegt."],
 "3.104":["Lagerverwaltung: die Artikelliste ist jetzt klappbar - jede Zeile zeigt zunächst nur Bezeichnung und Bestand, ein Klick zeigt die letzten Buchungen.",
  "Fehler behoben: die Kamera beim Barcode-Scan stellte auf manchen Geräten nicht scharf."],
 "3.105":["Fehler behoben: beim Erzeugen eines Einladungslinks fehlte auf manchen Geräten jede Rückmeldung - der Erfolg/Fehler steht jetzt direkt im Formular statt in einer Meldung, die dort stumm blieb.",
  "Neu: Lagerverwaltung - „Alle zuklappen” blendet die komplette Artikelliste auf einen Schlag aus.",
  "Kamera-Fokus beim Barcode-Scan weiter verbessert."],
 "3.106":["Neu: Lagerverwaltung - eine Materialposition kann jetzt mehrere, einzeln buchbare Produkte enthalten (z. B. verschiedene Rohrbogen-Varianten unter derselben Position).",
  "Neu: ein unbekannter Barcode beim Einscannen bietet direkt an, daraus ein neues Produkt anzulegen und einer Materialposition zuzuordnen.",
  "Der Barcode eines Artikels wird jetzt beim einzelnen Produkt in der Lagerverwaltung hinterlegt, nicht mehr im Material-Katalog."],
 "3.107":["Neu: beim Barcode-Scan lässt sich die Kamera per Antippen des Bilds neu fokussieren - hilft, wenn sie bei kurzer Distanz nicht von selbst scharfstellt."],
 "3.108":["Barcode-Scan: das Antippen zum Fokussieren wurde verstärkt - stellt die Kamera dabei immer noch nicht scharf, wird jetzt zusätzlich ein neues Kamerabild angefordert, was auf mehr Geräten wirkt."],
 "3.109":["Barcode-Scan: das Antippen zum Fokussieren nimmt jetzt zusätzlich ein Einzelfoto auf und sucht direkt darin nach dem Code - nutzt denselben Aufnahmeweg wie die normale Kamera-App, nicht nur den Video-Autofokus."],
 "3.110":["Fehler behoben: beim Barcode-Scan konnte das Kamerabild nach dem Antippen zum Fokussieren komplett schwarz bleiben - die dafür verantwortliche Änderung wurde zurückgenommen."],
 "3.111":["Barcode-Scan: das Antippen zum Fokussieren nimmt wieder zusätzlich ein Einzelfoto auf und sucht direkt darin nach dem Code - diesmal ohne den Kamera-Neustart, der zuvor zum schwarzen Bild führte."],
 "3.112":["Fehler behoben: die Einzelfoto-Aufnahme beim Antippen zum Fokussieren konnte das Kamerabild ebenfalls schwarz werden lassen - wurde wieder entfernt. Das Antippen bleibt vorerst ohne sichtbare Wirkung bei sehr kurzer Distanz."],
 "3.113":["Barcode-Scan: der Fokus-Mechanismus wurde neu aufgebaut - die Kamera-Vorschau wird jetzt vollständig angehalten, bevor ein Einzelfoto aufgenommen wird, und danach für die Weitersuche neu gestartet. Das soll das zuvor gemeldete schwarze Bild vermeiden."],
 "3.114":["Neu: Barcode-Scan - ein Code lässt sich jetzt auch von Hand eingeben, wenn die Kamera ihn partout nicht lesen kann.",
  "Barcode-Scan: die Kamera bekommt vor dem Einzelfoto mehr Zeit zum Scharfstellen."],
 "3.115":["Neu: Barcode-Scan - ein Knopf 'Andere Kamera-App verwenden' öffnet bei Bedarf die echte Kamera-App des Geräts statt der Web-Vorschau, was auf manchen Geräten deutlich schärfer fokussiert."],
 "3.116":["Fehler behoben: Barcode-Scan per Einzelfoto (Tippen zum Fokussieren und 'Andere Kamera-App verwenden') erkannte Codes bisher gar nicht, unabhängig von der Bildschärfe - ein Programmierfehler in der Bildauswertung ist jetzt korrigiert."],
 "3.117":["Fehler behoben: Barcode-Scan per Einzelfoto zeigte immer dieselbe Meldung 'Foto konnte nicht ausgewertet werden', auch wenn einfach kein Code im Bild war - die Meldung unterscheidet jetzt korrekt zwischen beiden Fällen und die Auswertung bleibt nicht mehr unbegrenzt lange hängen."],
 "3.118":["Neu: Lagerverwaltung - im Formular 'Neues Produkt erfassen' lässt sich die Materialposition jetzt per Suchfeld filtern, statt die ganze Liste durchscrollen zu müssen."],
 "3.119":["Barcode-Scan: die Kamera-App des Geräts öffnet sich jetzt sofort automatisch beim Einscannen/Ausscannen - kein zusätzlicher Klick auf 'Andere Kamera-App verwenden' mehr nötig."],
 "3.120":["Neu: Material einer Massaufnahme lässt sich mit dem Knopf '📤 Ab Lager ausbuchen' direkt als Abgang im Lager buchen. Das passiert nie von selbst - im Dialog sind Zeilen, Produkt und Menge vorher frei anpassbar, und wurde für dieselbe Massaufnahme schon ausgebucht, steht eine Warnung da."],
 "3.121":["Ab Lager ausbuchen: jetzt stehen auch die Halbfabrikate der Massaufnahme zur Wahl - bei einer Dachrinne also Rinnenböden, Stutzen, Rinnenhalter, Winkel und Dehnungsstücke. Das Blech selbst bleibt wie bisher aussen vor.",
  "Da ein Halbfabrikat keine EDV-Nr. trägt, wählen Sie die Materialposition dort selbst - mit Suchfeld. Die App schlägt eine vor, wählt sie aber nur bei einem eindeutigen Treffer."],
 "3.122":["Fotos: überall zwei getrennte Knöpfe statt einem - '📷 Foto aufnehmen' öffnet direkt die Kamera, '🖼️ Aus Galerie wählen' die Galerie (dort weiterhin mehrere Fotos auf einmal). Gilt in Massaufnahme, Ausmass, Offerte und Regierapport.",
  "Vorher entschied das Gerät selbst, was ein Antippen öffnet - je nach Modell kam nur die Kamera oder nur die Galerie."],
 "3.123":["Lagerverwaltung: beim Buchen wird jetzt das Objekt/Projekt verlangt. 'Werkstatt / Lager' ist dabei eine ausdrückliche Wahl - so fällt keine Buchung stillschweigend aus der Auswertung.",
  "Neu im Projekt: die Karte 'Material ab Lager' zeigt je Produkt, was für dieses Projekt verbraucht wurde, und lässt sich als Materialzusammenfassung drucken.",
  "Wird direkt aus einer Massaufnahme ausgebucht, ordnet die App das Projekt automatisch zu - dort wird nicht gefragt."],
 "3.124":["Lagerverwaltung: neues Suchfeld über der Liste. Gesucht wird in EDV-Nr., Bezeichnung, Dimension, Produktname UND Barcode - bei über 370 Positionen ist Scrollen kein Bedienweg mehr.",
  "Neu: Produkte, die gar nicht in der Regiematerialliste stehen, lassen sich jetzt erfassen. Im Dialog 'Neues Produkt' gibt es dazu 'Neue Materialposition anlegen' - die EDV-Nr. schlägt die App aus einem eigenen Nummernkreis vor (999.01, 999.02 …) und bleibt änderbar."],
 "3.125":["Ab Lager ausbuchen: die Materialposition eines Halbfabrikats wird jetzt direkt beim Tippen gefunden. Die Treffer stehen sofort als Liste da und werden angetippt - vorher musste man nach der Eingabe noch das Auswahlfeld aufklappen."],
 "3.126":["Neue Materialposition: die EDV-Nr. wird jetzt aus der PASSENDEN Katalogruppe vorgeschlagen. Ein neuer Rinnenboden bekommt die nächste freie Nummer bei 203 (Rinnenzubehör), eine Holzschraube bei 826 - mit Begründung darunter. Passen mehrere Gruppen gleich gut, legt die App sie als Knöpfe nebeneinander statt zu raten.",
  "Auch im Dialog 'Neues Produkt' erscheinen die Treffer zur Materialposition jetzt sofort beim Tippen - dort stand noch das alte Auswahlfeld."],
 "3.127":["Lagerverwaltung: Produkte lassen sich jetzt entfernen. Ohne Buchung wird wirklich gelöscht; sobald gebucht wurde, wird ARCHIVIERT - das Produkt verschwindet aus allen Listen, die Buchungen bleiben als Beleg stehen und '📦 Archiv anzeigen' holt es jederzeit zurück. War es das letzte Produkt seiner Position, lässt sich auf Nachfrage auch die Katalogposition entfernen.",
  "Der Knopf '＋ Neues Produkt' steht jetzt oben in der Lagerverwaltung. Die Hilfe hatte ihn schon genannt, es gab ihn aber nur innerhalb einer aufgeklappten Position.",
  "Sicherheit: die Firmengrenze auf der Produkt-Tabelle hat seit v3.106 nicht richtig gebunden (die beiden Schranken waren oder- statt und-verknüpft). Das ist behoben - Produkte sind jetzt so abgesichert wie die Buchungen."],
 "3.128":["Im Dialog 'Neues Produkt erfassen' steht das Suchfeld für die Materialposition jetzt IMMER da - auch dann, wenn die Position schon vorbelegt ist. Bisher verschwand es genau dann, und wer den Dialog über '＋ Weiteres Produkt zu dieser Position' öffnete, bekam es nie zu sehen. Tippen öffnet die Treffer, ein Klick wechselt die Position.",
  "Dasselbe im Ausbuchen-Dialog der Massaufnahme: auch dort bleibt das Suchfeld nach der Wahl stehen, statt nur einen '✏️ Position ändern'-Knopf zu hinterlassen."],
 "3.129":["Ausmass → Offerte erfassen: die fett gedruckten Titel aus der Offerte bilden jetzt klappbare Blöcke, genau wie in der Offerte selbst. Sie starten zugeklappt – bei einer langen Offerte steht so sofort ein Überblick da statt einer endlosen Liste.",
  "Im Titel steht, wie viele Positionen des Blocks schon fertig sind (z. B. '3/8 fertig'). So sieht man auch zugeklappt, wo noch Arbeit liegt. Positionen ohne Titel stehen weiterhin einfach in der Liste."],
 "3.130":["Einstellungen → Mitarbeiter: jedem Mitarbeiter lässt sich jetzt nachträglich eine E-Mail-Adresse zuordnen – auch einem, der schon lange angelegt ist. Die Person meldet sich danach zusätzlich mit dieser Adresse an (der Benutzername gilt unverändert weiter) und kann ein vergessenes Passwort selbst zurücksetzen.",
  "Das Eintragen ändert kein Passwort und verschickt keine Nachricht. Jede Adresse kann nur zu EINEM Konto gehören; eine schon vergebene lehnt die App mit einer verständlichen Meldung ab. Leer lassen entfernt die Adresse wieder."],
 "3.131":["Lagerverwaltung, Buchen-Dialog (auch nach einem Ein- oder Ausscannen): die Projektsuche beim Feld 'Objekt / Projekt' zeigt die Treffer jetzt SOFORT beim Tippen. Bisher stand dort ein Auswahlfeld, das seine gefilterte Liste erst beim Aufklappen zeigte - die Suche wirkte dadurch wie kaputt. 'Werkstatt / Lager' steht immer zuoberst.",
  "Damit ist die letzte Stelle dieser Bauart behoben; alle drei Suchfelder der Lagerverwaltung arbeiten jetzt gleich."],
 "3.132":["Mauerabdeckung: eine Gesamtbreite von 0 mm wird jetzt als Fehler gemeldet. Bisher nahm die App sie stillschweigend an und rechnete aus Saum und Umschlägen eine Abwicklung, die brauchbar aussah, aber zu einer Mauerabdeckung ohne Mauer gehörte.",
  "Dachfenstereinfassung: beim Material aus älteren, gespeicherten Aufnahmen werden die Bleilappen wieder mitgezählt. Bei dieser einen Art fehlten sie, weil sie als einzige nicht im Rückfall für alte Datensätze stand.",
  "Ansonsten Wartungsarbeit ohne sichtbare Änderung: die Prüfstände der App wurden auf den heutigen Stand gebracht (siehe Abschlussbericht)."],
 "3.133":["Regierapport drucken: die EDV-Nr. des Materials steht jetzt auch auf dem Papier. Die Spalte war im Ausdruck die ganze Zeit vorhanden – mit Überschrift und eigener Breite – aber leer, weil die Nummer in einem Suchfeld steht und im Druck jede Suche ausgeblendet wurde.",
  "Die Suchfelder über der Seite (Projektsuche, Materialsuche) bleiben im Ausdruck weiterhin weg, ebenso die Vorschlagsliste unter dem EDV-Feld."],
 "3.134":["Einstellungen → Material (und Blitzschutz-Material): der Excel-Import gleicht die Datei jetzt mit dem bestehenden Katalog ab, statt alles blind anzulegen. Eine Nummer, die es schon gibt, wird aktualisiert – bisher scheiterte der ganze Import daran oder erzeugte eine zweite Zeile.",
  "Vor dem Speichern steht da, was passiert: wie viele Positionen neu sind, wie viele geändert werden (mit altem und neuem Wert je Feld) und wie viele unverändert bleiben. Geschrieben wird nur, was sich wirklich ändert.",
  "Gelöscht wird nie: Positionen, die in der Datei fehlen, bleiben stehen. Und ein Feld, für das die Datei keine Spalte hat, behält seinen Wert, statt geleert zu werden. Dieselbe Nummer zweimal in einer Datei bricht den Import ab, bevor irgendetwas geschrieben wird."],
 "3.135":["Einstellungen → Material (und Blitzschutz-Material): über dem Excel-Import steht jetzt „Wie muss die Excel-Datei aufgebaut sein?\" – aufklappbar, und zwar BEVOR man die Datei auswählt. Darin steht jede Spalte, ob sie Pflicht ist und wie ihre Überschrift heissen darf. Bisher stand das erst im Vorschaufenster, also erst nach der Dateiwahl.",
  "Der Hinweis wird aus den Feldern des Imports selbst erzeugt. Kommt später eine Spalte dazu, steht sie automatisch auch im Hinweis – er kann nicht veralten.",
  "Steht in einer Preisspalte Text statt einer Zahl (z. B. „Fr. 7.90\"), sagt die Vorschau das jetzt. Bisher wurde daraus stillschweigend 0.00 – und das fiel erst auf, wenn jemand den Preis brauchte. Eine echte Null („0.00\" oder „-\") gilt weiterhin als gewollt."],
 "3.136":["Lagerverwaltung, neues Produkt (auch nach einem Scan): sobald die Bezeichnung getippt ist, stehen die passenden Materialpositionen ganz oben in der Trefferliste – ohne zusätzlichen Klick. Ein Tipp übernimmt sie.",
  "Passt genau eine Position deutlich am besten, steht „✓ Vorschlag der App\" daneben. Passen mehrere ähnlich gut, sagt die App das ausdrücklich statt sich festzulegen. Passt nichts, behauptet sie nichts. Vorgewählt wird nie etwas – ein Tippfehler soll keinen Bestand auf die falsche Position buchen.",
  "Der ganze Katalog bleibt darunter erreichbar, und wer selbst sucht, hat Vorrang: während getippt wird, tritt der Vorschlag zurück."],
 "3.137":["Einstellungen → Material: „＋ Material hinzufügen\" brach ab dem zweiten Klick mit einer Datenbankmeldung ab („duplicate key value violates unique constraint\"). Der Knopf trug die EDV-Nr. als festen Text ein – beim zweiten Mal war sie schon vergeben.",
  "Die Nummer wird jetzt berechnet, mit derselben Funktion wie in der Lagerverwaltung: die nächste freie Nummer im eigenen Kreis (999.xx), die Sie danach überschreiben können. Sollte eine Nummer im selben Augenblick von jemand anderem belegt werden, rechnet die App neu und meldet erst dann – in verständlichen Worten statt mit dem rohen Datenbanktext."],
 "3.138":["Neues Material anlegen geht jetzt überall gleich: „＋ Material hinzufügen\" in den Einstellungen öffnet denselben Dialog wie „Neue Materialposition anlegen\" in der Lagerverwaltung – mit Bezeichnung, Dimension, Einheit, Preis und dem begründeten Nummernvorschlag. Bisher legte der Knopf stumm eine leere Zeile an, die man danach in der Liste ausfüllen musste.",
  "Ein Schalter oben im Dialog entscheidet, ob zur Katalogposition gleich ein Lager-Produkt (mit Barcode) entsteht. Aus der Lagerverwaltung ist er gesetzt, aus dem Katalog nicht – umstellen lässt er sich jederzeit, man kann also nicht im falschen Dialog landen.",
  "Aus der Lagerverwaltung bleibt der Ablauf unverändert."],
 "3.139":["Wird zusammen mit der Materialposition gleich ein Lager-Produkt angelegt, gibt es die Bezeichnung nur noch EINMAL. Bisher standen zwei Felder da – eines fürs Produkt, eines für die Position – und dasselbe musste zweimal getippt werden.",
  "Die EDV-Nr. hängt an dieser Bezeichnung: „Rinnenstutzen 120mm\" bekommt eine Nummer aus der Rinnen-Gruppe 203, „Spenglerschrauben 5x50\" eine aus 826 – mit der Begründung daneben („✓ Gruppe 203 – dort steht bereits ‚Rinnenstutzen 100mm'\"). Passt nichts, gibt es eine Nummer aus dem eigenen Lager-Kreis 999. Das rechnet sich bei jedem getippten Zeichen neu, solange Sie die Nummer nicht selbst anfassen."],
 "3.140":["Neues Material anlegen ist nicht mehr versteckt. In der Lagerverwaltung steht „＋ Neues Material / Produkt\" jetzt als erster, blauer Knopf der Leiste – damit brauchen Sie die Einstellungen dafür gar nicht mehr zu öffnen.",
  "In den Einstellungen steht der Anlege-Knopf jetzt ÜBER der Liste statt darunter. Bisher sass er hinter bis zu 20 Materialzeilen und den Blätter-Knöpfen – zu finden nur, wenn man ohnehin bis ans Ende scrollte.",
  "Und jeder Knopf sagt jetzt, was er anlegt: „＋ Neue Materialposition\" (Regierapport), „＋ Material für Massaufnahmen\", „＋ Neuer Blitzschutz-Artikel\", „＋ Blech erfassen (Rolle / Tafel)\". Vorher hiessen drei davon wortgleich „＋ Material hinzufügen\"."],
 "3.141":["Im Anlege-Dialog steht jetzt „Gewählt: …\" vor der Materialposition, und der Knopf daneben heisst „↩ andere wählen\" statt „✏️ ändern\". „Ändern\" klang nach „diese Position bearbeiten\" – gemeint war immer „eine andere wählen\".",
  "Zur Erinnerung, weil danach gefragt wurde: „➕ Neue Materialposition anlegen …\" ist der letzte Eintrag der Trefferliste und die Alternative zu den Positionen darüber – passt keine, legen Sie eine neue an. Der Knopf daneben ist der Rückweg: er nimmt die getroffene Wahl zurück und öffnet die Liste wieder."],
 "3.142":["Im Projekt gibt es jetzt den Abschnitt „📷 Alle Fotos\": jedes Bild des Objekts an EINEM Ort – aus den Massaufnahmen (Fotos und Skizzen), dem Ausmass, den Regierapporten, den Offerten und den Projektdateien.",
  "Unter jedem Bild steht, woher es stammt – zum Beispiel „📐 Kamineinfassung · Ost · Foto 2/3\" oder „📋 Regierapport · 14.03.2026\". Ein Tipp zeigt das Bild gross.",
  "Es ist eine reine Übersicht: hinzugefügt und gelöscht werden Fotos weiterhin dort, wo sie hingehören. Die Vorschauen werden erst geladen, wenn der Abschnitt aufgeklappt ist."],
 "3.143":["Die EDV-Nr. im Materialkatalog und die Artikel-Nr. beim Blitzschutz sind jetzt JE FIRMA eindeutig. Bisher galten sie firmenübergreifend: sobald eine Firma eine Nummer benutzte, war sie für jede andere Firma für immer gesperrt – obwohl die den fremden Katalog gar nicht sehen kann.",
  "Für Sie heisst das: beim Anlegen einer Materialposition oder beim Excel-Import kann der Fehler „duplicate key … materials_edv_nr_key\" nicht mehr aus dem Nichts auftauchen. Innerhalb Ihrer eigenen Firma bleibt jede Nummer weiterhin nur einmal vergeben – daran ändert sich nichts.",
  "Die Firmengrenze selbst ist unverändert: welche Daten Sie sehen, entscheidet weiterhin allein die Datenbank."],
 "3.144":["Der Abschnitt „📷 Alle Fotos\" hat einen Knopf „🖨️ Fotodokumentation\" bekommen: alle Bilder des Objekts auf Papier oder als PDF – mit Firmenkopf, Projekt und Auftraggeber, und unter jedem Bild wieder die Herkunft.",
  "Gedacht als das Blatt, das der Kunde nach der Sanierung bekommt oder das bei einer Reklamation auf den Tisch kommt. Gedruckt wird genau das, was der Abschnitt zeigt.",
  "Der Druck wartet, bis jedes Bild wirklich geladen ist – sonst blieben auf dem Papier leere Kästen. Bei vielen Fotos dauert das einen Moment; das Fenster sagt so lange, dass es vorbereitet wird."],
 "3.145":["Die Fotodokumentation nutzt das Blatt jetzt richtig aus: vier Bilder auf der ersten A4-Seite (zwei Spalten, zwei Reihen), sechs auf jeder Folgeseite ohne Briefkopf. Vorher bestimmte das Bildformat die Höhe – ein hochkant aufgenommenes Foto riss die Reihe auseinander und es passten oft nur zwei aufs Blatt.",
  "Jede Kachel ist jetzt gleich gross, egal ob hoch, quer oder quadratisch aufgenommen. Abgeschnitten wird nichts: ein Hochformat bekommt seitlich Luft, statt die Reihe zu sprengen."],
 "3.146":["Die Anleitung ist wieder aktuell. Sie stand auf Version 3.44 – die App war 100 Versionen weiter, und das PDF beschrieb eine App, die es so nicht mehr gibt.",
  "Neu beschrieben: die Lagerverwaltung mit Barcode, Material ab Lager buchen, die Unterschriften im Regierapport, „Was ist neu\", die Fotowand und die Fotodokumentation. Korrigiert: es sind dreizehn Massaufnahme-Arten, nicht zwölf – die Dachfenstereinfassung fehlte ganz.",
  "Öffnen lässt sie sich wie bisher über den i-Knopf („📖 Ganze Anleitung\") oder unter Einstellungen → Allgemein → 📖 Anleitung."],
 "3.147":["Der Abschnitt „📷 Alle Fotos\" ist jetzt chronologisch sortiert – das Neueste zuerst. An jedem Bild steht neu auch das Datum seines Eintrags (Massaufnahme, Rapport, Hochladen); wann ein Foto wirklich aufgenommen wurde, weiss die App nicht.",
  "Neu: eine Filterleiste zeigt eine einzelne Herkunft allein an – etwa nur die Rapportfotos. Die Fotodokumentation druckt dann genau diesen Auszug und sagt es auch."],
 "3.148":["Beim Anlegen eines Mitarbeiterkontos lässt sich jetzt gleich eine E-Mail-Adresse angeben. Sie wird zur zusätzlichen Anmeldeadresse, und die Zugangsdaten gehen zusätzlich per E-Mail hinaus. Bisher liess sie sich erst nachtragen – und dann kam keine E-Mail mehr, weil der Versand am Anlegen hängt.",
  "Lagerverwaltung: wird ein Produkt samt neuer Materialposition angelegt, darf die Position jetzt anders heissen als das Produkt („Stahlblech svz\" gegenüber „Stahlblech svz 0,6 × 670 Rolle\"). Voreingestellt bleibt es wie bisher bei einer Bezeichnung für beide."],
 "3.149":["Neu: aus den Positionen einer Offerte lassen sich die Massaufnahmen des Auftrags ableiten. Ein Dialog schlägt zu jeder Position die passende Massaufnahme-Art vor – „Dachrinne halbrund 333mm\" wird zur Dachrinne –, und die angehakten entstehen auf einen Schlag im Projekt: leer, aber mit Titel, Art und dem Bezug zur Offerte.",
  "Was die App nicht einordnen kann, sagt sie und schlägt „Skizze/Foto\" vor; was im Projekt schon unter demselben Titel steht, wird nicht noch einmal angehakt. Für eine einzelne Position gibt es den Knopf 📐 direkt in der Positionszeile."],
 "3.150":["Neu: eine zweite Ansicht, die nach dem Arbeitsablauf gegliedert ist statt nach Modulen – unten eine Leiste mit Heute, Projekte, Werkstatt, Lager und Mehr, und als Startseite die eigenen offenen Aufgaben. Einzuschalten auf der Startseite mit „✨ Neue Ansicht testen“.",
  "Im Projekt zeigt eine Ablaufleiste auf einen Blick, wo es steht: Offerte, Massaufnahme, Freigabe, Rüsten, Montage, Ausmass.",
  "Die klassische Ansicht bleibt vollständig erhalten. Beide arbeiten mit denselben Formularen und denselben Daten – zurück geht es jederzeit unter „Mehr“."],
 "3.151":["Die neue Ansicht ist jetzt die Vorgabe. Wer lieber die gewohnte will, findet sie unverändert unter „Mehr → Zurück zur klassischen Ansicht“ – die Wahl merkt sich jedes Gerät für sich.",
  "Neu: ein Projekt öffnet eine eigene Seite mit sechs Registern – Übersicht, Aufmass, Produktion, Werkstatt, Ausmass und Mehr. Die Produktion zeigt den Zuschnitt-Fortschritt je Massaufnahme und fürs ganze Projekt.",
  "Das Firmenlogo steht wieder auf der Startseite, und die Einstellungen sehen jetzt aus wie die neue Ansicht."],
 "3.152":["Das Massaufnahme-Formular sieht jetzt ebenfalls aus wie die neue Ansicht: grössere Eingabefelder, die sich mit Handschuhen treffen lassen, und eine Schriftgrösse, bei der das Handy beim Hineintippen nicht mehr ins Feld hineinzoomt.",
  "Die Stück- und Zuschnittlisten bleiben absichtlich schmal – dort stehen mehrere Felder in einer Zeile, und grössere Felder würden die Liste unlesbar machen.",
  "An den Massen, der Abwicklung und dem Zuschnitt wurde nichts geändert."],
 "3.153":["Neu in der Werkstatt: der Umschalter „Nach Projekt / Nach Material“. Nach Material zählt alle Zuschnitte einer Materialstärke zusammen – quer über Projekte hinweg. Das ist die Reihenfolge, in der tatsächlich gerichtet wird: einmal zur Rolle, alles davon schneiden, weglegen.",
  "Getrennt wird nach Material UND Stärke – 0,7er und 0,8er Titanzink kommen von verschiedenen Rollen.",
  "Die Materialsicht ist eine Rüstliste; abgehakt wird weiterhin an der Massaufnahme, wo die Stücknummern stehen. Ein Tipp führt hin."],
 "3.154":["Jetzt sehen auch Regierapport, Ausmass, Offerte und Leistung aus wie die neue Ansicht: grössere Eingabefelder für Finger mit Handschuhen, rundere Knöpfe, ruhigere Überschriften.",
  "Der gedruckte Regierapport bleibt davon unberührt – auf Papier und im PDF steht Zeichen für Zeichen dasselbe wie vorher.",
  "Die Felder innerhalb der Arbeits-, Material- und Positionszeilen bleiben absichtlich schmal: dort stehen sechs bis sieben nebeneinander.",
  "Behoben: die Knöpfe „Foto aufnehmen“ und „Aus Galerie wählen“ waren in der neuen Ansicht kleiner geworden statt grösser."],
 "3.155":["Die Anleitung zeigt jetzt die neue Ansicht – also das, was du beim Öffnen der App tatsächlich siehst. Bisher zeigten ihre Bilder die klassische, obwohl seit Version 3.151 niemand mehr mit ihr startet.",
  "Neu abgebildet: die Projektseite mit ihren sechs Registern. Sie war beschrieben, aber nie zu sehen.",
  "Drei Bilder bleiben absichtlich klassisch – Startseite und Aufgabenkarte gibt es nur dort; in der neuen Ansicht sind sie die Seite „Heute“."],
 "3.156":["Werkstatt, Lager, Suche, Einstellungen und alles Weitere bleiben jetzt IM Rahmen der neuen Ansicht: die untere Leiste verschwindet nicht mehr, und oben steht, wo du bist. Bisher legte sich der alte Seitenaufbau darüber.",
  "Das Lager ist ein eigener Bereich, keine Einstellungsseite mehr.",
  "„＋ Neues Projekt“ zeigt nur noch das Formular – nicht noch einmal die Projektliste, von der du gerade kamst. Archiv und Filter haben einen eigenen Knopf.",
  "Der Regierapport steht neben den anderen Registern des Projekts statt unter „Mehr …“.",
  "Felder und Knöpfe sind wieder so gross wie vorher – die Vergrösserung aus 3.152/3.154 ist zurückgenommen.",
  "Behoben: im gedruckten Regierapport standen in zwei Feldern unten rechts zwei kleine Schrägstriche. Das war der Anfasser des Textfelds; auf Papier hat er nichts zu suchen."],
 "3.157":["Im Lager steht jetzt wirklich nur die Lagerverwaltung. Materialbestand und Reststücke sind Firmeneinstellungen und stehen weiterhin unter Einstellungen → Lager.",
  "„Anleitung“ öffnet jetzt die Anleitung. Bisher führte der Eintrag in die Einstellungen – genauso wie „Einstellungen“ direkt darüber.",
  "Die offenen Aufgaben und die Listen der einzelnen Massaufnahmen sind deutlich kompakter: kleinere Karten, kleinere Knöpfe, und der blaue Knopf spannt sich nicht mehr über die ganze Karte.",
  "Das Register „Aufmass“ heisst jetzt „Massaufnahme“."],
 "3.158":["Die Startseite ist neu aufgebaut – nach dem Prototyp: zuoberst, was dringend ist, darunter deine Aufgaben, die Werkstatt in drei Zahlen, die anstehenden Montagen und die offenen Projekte mit ihrem Produktionsstand.",
  "Die Aufgaben sind jetzt Zeilen statt Karten. Ein Tippen öffnet die Massaufnahme; wo es einen eigenen Schritt gibt (rüsten, montieren, zuweisen), steht er als Knopf daneben.",
  "„Werkstatt heute“ rechnet mit denselben Zahlen wie die Werkstatt selbst – nicht mit einer zweiten Rechnung.",
  "Die anstehende Montage zeigt bewusst kein geplantes Datum: einen Montagetermin führt die App nicht. Sie zeigt, seit wann etwas bereitliegt und wer eingeteilt ist."],
 "3.159":["In den Bereichen der neuen Ansicht (Werkstatt, Lager, Projekte, Suche, Cockpit) ist der Knopf „🏠 Start“ verschwunden. Er führte dort an dieselbe Stelle wie „✓ Fertig“ – und trug dabei den falschen Namen. Der Weg nach Hause ist „Heute“ in der Leiste unten.",
  "In den Formularen (Massaufnahme, Ausmass, Offerte, Regierapport) bleibt „🏠 Start“ stehen: dort liegt die Leiste verdeckt unter dem Formular."],
 "3.160":["Neu: ein Feld <b>Wichtige Hinweise</b> beim Projekt (Stammdaten bearbeiten) – „Baustellenzufahrt nur bis 16:00 Uhr“, „Schlüssel beim Hauswart“. Die Notiz steht auf der Startseite ganz oben und auf der Projektseite.",
  "Neu: <b>Montage geplant am</b> im Arbeitsstatus der Massaufnahme. Die Startseite sagt unter „Anstehende Montage“ jetzt „morgen“ oder „in 2 Tagen“ statt nur, seit wann die Teile bereitliegen – und die Zeilen mit Termin stehen zuoberst.",
  "Der Montagetermin ist Planung, kein Arbeitsschritt: er lässt sich jederzeit verschieben und lässt eine Freigabe nicht verfallen.",
  "Ohne eingetragenen Termin wird weiterhin keiner geschätzt."],
 "3.161":["Ein Projekt lässt sich jetzt <b>Mitarbeitern zuteilen</b> – in den Stammdaten, auch an mehrere. Auf der Startseite erscheint es unter „Offene Projekte“ dann nur noch bei diesen Personen.",
  "Über der Liste stehen <b>Meine</b> und <b>Alle</b>. „Meine“ ist die Vorgabe; „Alle“ zeigt wieder den ganzen Betrieb – derselbe Umschalter, den die Werkstatt schon hat.",
  "Das ist eine Anzeige, keine Sperre: über „Projekte“ und die Suche bleibt jedes Projekt für alle erreichbar.",
  "Ist niemand zugeteilt, gilt die Person, die das Projekt angelegt hat. Für bestehende Projekte ändert sich damit zunächst nichts."],
 "3.162":["Die <b>Leiste unten bleibt überall stehen</b> – auch während eine Massaufnahme, ein Ausmass, eine Offerte, eine Leistung oder ein Regierapport offen ist. Bisher verschwand sie dort.",
  "Sind dabei ungespeicherte Eingaben im Formular, fragt die App vor dem Wechsel nach. Bei „Nein“ bleibt alles, wie es war.",
  "„Stammdaten bearbeiten“ zeigt jetzt nur noch die Stammdaten – nicht mehr das ganze Projekt-Cockpit mit allen Bereichen darunter.",
  "Die Knöpfe der Massaufnahme-Auswahl sind deutlich kompakter: Symbol und Text nebeneinander statt untereinander.",
  "Folge davon: „🏠 Start“ verschwindet auch in den Formularen – die Leiste mit „Heute“ liegt jetzt ja darunter."],
 "3.163":["<b>Der letzte Administrator einer Firma kann sich das Recht nicht mehr selbst entziehen.</b> Vorher führte das in eine Sackgasse: ohne Administrator kann niemand mehr Rechte vergeben – auch nicht, um ihn zurückzugeben. Der Haken ist jetzt gesperrt, und die Datenbank weist es zusätzlich ab.",
  "Die Lagerverwaltung steht nicht mehr in den Einstellungen. Sie hat seit 3.157 ihren eigenen Bereich in der Leiste; in den Einstellungen bleiben Materialbestand und Reststücke.",
  "Projekt → „Mehr …“ → „Dateien, Fotos und Verlauf“ zeigt jetzt genau das – und nicht mehr das ganze Projekt-Cockpit."],
 "3.164":["<b>Eine Auftrags-Nr. gibt es je Firma nur noch einmal.</b> Wird eine Nummer eingegeben, die schon vergeben ist – beim Anlegen eines Projekts oder beim Bearbeiten der Stammdaten – meldet die App, zu welchem Projekt sie gehört, und speichert nicht.",
  "Damit entstehen nicht mehr zwei Projekte zur selben Baustelle, auf die sich Massaufnahmen, Rapporte und Ausmasse dann aufteilen.",
  "Verglichen wird ohne Rand-Leerzeichen und ohne Gross-/Kleinschreibung. Archivierte Projekte halten ihre Nummer belegt; andere Firmen haben ihre eigenen Nummernkreise."],
 "3.165":["<b>In der Rapportliste steht jetzt, worum es in jedem Rapport geht.</b> Unter den Kopfdaten: die Arbeitstexte, die Stundensumme und die Anzahl Materialzeilen – in der Projektliste, in der neuen Ansicht und in der Rapport-Übersicht.",
  "Vorher sahen fünf Rapporte zur selben Baustelle alle gleich aus; man musste jeden einzeln öffnen.",
  "Die Zeile wird abgeleitet, nicht getippt: sie gilt rückwirkend für alle bestehenden Rapporte und ändert sich mit, wenn jemand die Arbeitszeilen anpasst. Ist nichts erfasst, bleibt sie weg."],
 "3.166":["<b>Ein Projekt geht jetzt überall auf der Projektseite auf</b> – auch wenn der Klick aus der <b>Werkstatt</b>, aus der Projektliste oder aus der Suche kommt. Vorher klappte dort mitten in der neuen Ansicht das vollständige alte Cockpit auf.",
  "„Bearbeiten“ in der Projektliste zeigt ebenfalls nur noch die Stammdatenfelder statt des ganzen Cockpits.",
  "Ein Suchtreffer auf eine einzelne Massaufnahme, ein Ausmass oder einen Rapport führte vorübergehend noch ins Cockpit – seit 3.167 nicht mehr, siehe unten."],
 "3.167":["<b>Ein Suchtreffer springt jetzt auch auf der Projektseite an die richtige Stelle.</b> Die App schlägt das passende Register auf – Massaufnahme, Ausmass oder Regierapport – und hebt den getroffenen Eintrag kurz hervor.",
  "Damit führt kein Weg aus der Suche mehr ins alte Cockpit.",
  "Gibt es den Eintrag nicht mehr, geht das Projekt trotzdem auf – einfach ohne Hervorhebung. Es wird nichts erfunden und keine Meldung über etwas gezeigt, das man nicht zu verantworten hat."],
 "3.168":["<b>Das Zählwerk: die App lernt aus der eigenen Firmengeschichte.</b> Den Anfang macht die EDV-Nr.-Suche im Regierapport – die Vorschläge sind jetzt nach der eigenen Benutzung geordnet, mit „5× benutzt“ daneben.",
  "Es wird nichts ausgeblendet: dieselben Treffer, dieselbe Obergrenze von fünfzehn, nur eine bessere Reihenfolge. Und es wird keine Zahl gesetzt – Mengen und Preise bleiben unberührt.",
  "Gezählt wird über Rapporte und das Material an den Massaufnahmen, immer nur innerhalb der eigenen Firma. Am Anfang ist das Zählwerk fast still: es fängt an zu helfen, sobald es etwas weiß, und behauptet vorher nichts."],
 "3.169":["<b>Das Zählwerk kennt jetzt auch die Massaufnahme-Art.</b> Beim Material an einer Massaufnahme steht vorne, was bei <b>dieser Art</b> schon erfasst wurde – „7× bei dieser Art“. Ist dazu noch nichts bekannt, zählt wie bisher die Gesamtzahl des Betriebs.",
  "<b>Im Ausmass</b> trägt eine Position, die in früheren Ausmassen fast nie eine Menge bekommen hat, einen Hinweis: „⚠️ in 7 von 8 Ausmassen nicht gebraucht“.",
  "Das ist ein Hinweis, keine Sperre – die Zeile bleibt sichtbar und bedienbar. Und die App sagt erst etwas, wenn dieselbe Position mindestens dreimal vorgekommen ist; aus einem einzigen Ausmass etwas zu folgern wäre geraten."],
 "3.170":["<b>Arbeitstexte im Regierapport werden vorgeschlagen.</b> Beim Tippen in das Feld „Arbeit“ erscheinen die Sätze, die der Betrieb schon geschrieben hat – die häufigsten zuerst. Das Feld bleibt frei: ein neuer Text lässt sich wie bisher einfach eintippen.",
  "<b>Bei der Zuteilung</b> steht unter der Ankreuzliste, wer bei <b>diesem Auftraggeber</b> sonst zugeteilt ist – zum Antippen. Angekreuzt wird nichts von selbst; die Zuteilung bleibt eine Entscheidung.",
  "Beides rechnet aus dem, was ohnehin da ist. Der Zuteilungs-Vorschlag braucht dafür nicht einmal eine zusätzliche Abfrage."],
 "3.171":["<b>Die Arbeitstext-Vorschläge im Regierapport kommen jetzt nur noch aus dem Rapport, der gerade offen ist</b> – nicht mehr aus allen Rapporten der Firma.",
  "In einem Rapport wiederholt sich dieselbe Arbeit oft über mehrere Tage und Zeilen; genau dort spart ein Vorschlag Tipparbeit. Sätze aus fremden Baustellen waren dabei nur Beiwerk.",
  "Ein fertig geschriebener Satz steht den anderen Zeilen sofort zur Verfügung – beim Verlassen des Feldes, nicht beim Tippen. Ein frischer Rapport hat noch keine Vorschläge."],
 "3.172":["<b>Richtwerte aus echten Aufnahmen.</b> Neben dem leeren Massfeld steht bisher der Richtwert aus den Einstellungen. Jetzt steht daneben, was der Betrieb an dieser Stelle <b>wirklich gemessen</b> hat – „3× so gemessen“.",
  "Weichen die beiden ab, sind es <b>zwei</b> Knöpfe: der hinterlegte Richtwert und die eigene Messung, farblich unterschieden. Der Richtwert verschwindet nie, und eingetragen wird weiterhin nur, was angetippt wird.",
  "Das gilt in neun Aufnahme-Arten an jedem Feld, das schon bisher einen Richtwert hatte. Gezählt werden nur gemessene Felder – Abwicklung, Zuschnitte und Flächen sind gerechnet und werden nicht zurückgespiegelt. Ab der zweiten Messung sagt die App etwas; eine einzelne Aufnahme ist ein Bau, keine Gewohnheit."],
 "3.173":["<b>Das Zählwerk lernt jetzt auch die Auswahlfelder.</b> Neben einer noch leeren Auswahl steht, was der Betrieb üblicherweise nimmt – „3× gewählt: Prefa 0.7 braun“. Das gilt fürs <b>Material in jeder Art</b> und dazu für Abwicklung und Montageseite beim Einlaufblech sowie für die Abwicklung der Kehle.",
  "Damit sind auch <b>Einlaufblech konisch, Freies Profil und Rinne (Profil)</b> dabei. Diese drei haben keine gemessenen Richtwerte: ihre Standardwerte stehen in den Einstellungen und gehen von dort direkt in die Rechnung, im Formular werden sie gar nicht abgefragt. Ein Richtwert-Chip liesse sich dort nur bauen, indem man Felder erfindet, die es fachlich nicht gibt.",
  "Abwicklung, Montageseite und Kehlenabwicklung starten mit einer fest einprogrammierten Vorgabe (250 mm, von links, 500 mm). Genau die darf der Hinweis in Frage stellen. Hat jemand selbst etwas anderes gewählt, schweigt die App – eine eigene Entscheidung wird nicht kommentiert."],
 "3.174":["<b>„Was die App gelernt hat“.</b> Eine Seite, auf der alles steht, was das Zählwerk über diese Firma weiss – Material, Material je Art, Masse, Auswahlen und die selten gebrauchten Ausmass-Positionen. Dazu jeweils, wo es in der App auftaucht. Zu finden unter <b>Mehr</b> (neue Ansicht) oder auf dem Startbildschirm (klassische Ansicht).",
  "Die Zahlen sind <b>gerechnet, nicht gespeichert</b>: sie entstehen beim Nachschlagen aus euren Rapporten, Massaufnahmen und Ausmassen. Deshalb lässt sich dort nichts geradebiegen – stimmt eine Zahl nicht, stimmt der Datensatz nicht, aus dem sie kommt.",
  "<b>Widersprechen geht trotzdem:</b> ein Schalter ganz unten nimmt sämtliche Hinweise zurück. Die App verhält sich dann wie vor Version 3.168. Die Übersicht bleibt stehen, damit nachsehbar ist, worauf gerade verzichtet wird."],
 "3.175":["<b>Der Zurück-Knopf oben links geht jetzt einen Schritt, nicht zwei.</b> Lag über einem Bereich noch ein Dialog, schloss der Knopf den <b>Bereich darunter</b> – der Dialog blieb stehen. Für den Anwender sah es aus, als passiere nichts; in Wirklichkeit war der Bereich darunter stillschweigend weg.",
  "Jetzt geht zuerst der oberste Schirm zu. Liegt nichts darüber, schliesst der Knopf wie bisher den Bereich beziehungsweise führt von der Projektseite in die Projektliste zurück.",
  "Ausserdem behoben: die neue Seite „Was die App gelernt hat“ räumte die Kopfzeile nicht auf, wenn man sie über ihren eigenen Knopf verliess – danach zeigte die Kopfzeile einen Bereich an, den es nicht mehr gab."],
 "3.176":["<b>Werkstoff, Artikel und Bestand sind jetzt auseinanderzuhalten.</b> Bis hierher hiess alles drei „Material“: der Kupfer/Titanzink in der Massaufnahme, die EDV-Position im Katalog und die Blechzeile im Lager. In der Massaufnahme heisst das Feld jetzt <b>Werkstoff</b> – Katalog und Lager behalten „Material“.",
  "<b>Der Name eines Blechs steht nur noch an einer Stelle.</b> Die Lagerzeile trug bisher eine Kopie des Katalognamens, und die war schon auseinandergelaufen: im Katalog „Cava-Band Kupfer“, an der Lagerzeile nur „Cava-Band“. Jetzt zeigt die Lagerzeile den Katalognamen; geändert wird er einmal, im Katalog.",
  "<b>Jede Katalogposition kann sagen, woraus sie ist.</b> Im Materialkatalog gibt es ein Feld Werkstoff – nur bei Blech nötig. Eure sechs Blechpositionen sind bereits zugeordnet. Der Zuschnitt rechnet unverändert weiter wie bisher; umgestellt wird erst, wenn die Zuordnung vollständig ist."],
 "3.177":["<b>Ein Blech ist jetzt EIN Eintrag.</b> Bis hierher war ein Blech zweimal erfasst: der Artikel im Katalog trug den Namen, eine eigene Zeile im Materialbestand trug Stärke, Ausführung und Rolle/Tafel. Jetzt steht beides am Artikel. Eure sechs Bleche sind bereits übernommen – ihr müsst nichts nacherfassen.",
  "<b>Gleich benannte Bleche sind endlich zu unterscheiden.</b> Eure Positionen 102.01, 102.02 und 102.03 heissen alle drei „Kupferblech“. Überall, wo ein Artikel erscheint – Lagerverwaltung, Buchen, Ausbuchen, Suche –, steht jetzt sein Format dabei: „102.01 Kupferblech · 0,6 mm · Blank · Rolle“. Die Suchfelder finden damit auch nach Stärke und Form.",
  "<b>Warum das nötig war:</b> bisher stand dort die Spalte „Dim“, ein freies Textfeld. Bei den Kupferblechen war das zufällig die Stärke – beim Cava-Band steht dort aber „250mm“, und das ist die <b>Breite</b>. Wer sich darauf verliess, las dieses Blech als 250 mm dick.",
  "<b>Der Materialbestand bearbeitet ab jetzt den Katalogartikel.</b> Ein Eintrag braucht deshalb einen Artikel. „Entfernen“ löscht den Artikel <b>nicht</b> – es nimmt ihm nur das Format, sodass der Zuschnitt nicht mehr mit ihm rechnet. EDV-Nr., Preis, Barcode und alle Buchungen bleiben.",
  "<b>Der Werkstoff „Stahl, verzinkt“ heisst jetzt „Stahl“.</b> Die Dehnungswerte dahinter bleiben unverändert, und bereits gespeicherte Massaufnahmen lesen sich weiterhin."],
 "3.178":["<b>Warnung beim Löschen einer Materialposition korrigiert.</b> Wird in der Lagerverwaltung die letzte Produktzeile einer Position entfernt, fragt die App, ob auch die Katalogposition weg soll. Diese Rückfrage stammte noch aus der Zeit vor 3.177 und versicherte, Einträge im Blech-Materialbestand „bleiben bestehen“.",
  "Seit 3.177 stimmt das nicht mehr: das Format gehört zur Position selbst und wird mit ihr gelöscht. Die Rückfrage sagt das jetzt – samt Format („0,6 mm · Blank · Rolle“) und dem Hinweis, dass der Zuschnitt danach nicht mehr mit diesem Blech rechnet. Für Reststücke gilt unverändert: sie bleiben und verlieren nur ihre Zuordnung."],
 "3.179":["<b>Ein neues Blech wird nur noch EINMAL erfasst.</b> Bis hierher musste zuerst im Materialkatalog eine Position angelegt und danach im Materialbestand ihr Format gesetzt werden – zwei Karten, zwei Formulare für ein Blech.",
  "Jetzt steht in der Artikel-Auswahl des Materialbestands <b>„＋ neue Katalogposition anlegen …“</b>. Wird sie gewählt, erscheinen EDV-Nr., Bezeichnung und Einheit gleich im selben Dialog. Einmal speichern legt die Position an und setzt ihr Format. Die EDV-Nr. wird dabei aus der passenden Katalogruppe vorgeschlagen, genau wie in der Lagerverwaltung.",
  "Eine schon vergebene EDV-Nr. wird abgewiesen, bevor irgendetwas geschrieben wird – mit dem Hinweis, dass sich diese Position oben direkt auswählen lässt.",
  "<b>Nebenbei behoben:</b> wurde aus der Lagerverwaltung eine Materialposition angelegt, füllte die App zwei ihrer vier internen Listen nicht nach. Werkstoff und Format einer frisch angelegten Position konnten dadurch erst nach einem Neuladen stimmen."],
 "3.180":["<b>Auch der Werkstoff entsteht jetzt im selben Dialog.</b> Fehlt beim Erfassen eines neuen Blechs auch der Werkstoff, steht in der Werkstoff-Auswahl <b>„＋ neuen Werkstoff anlegen …“</b>. Name und die beiden Dehnungswerte erscheinen gleich dort. Einmal speichern legt Werkstoff, Katalogposition und Format an – in dieser Reihenfolge.",
  "Die Dehnungswerte bleiben dabei bewusst <b>beim Werkstoff</b> und wandern nicht an die Katalogposition. Es gibt sechs Werkstoffe und über 380 Positionen – an jeder einzelnen stünden dieselben zwei Zahlen, und ein Werkstoff muss wählbar bleiben, auch wenn gerade kein Blech daraus am Lager liegt.",
  "Die Karte <b>Werkstoffe</b> unter Einstellungen → Massaufnahmen bleibt deshalb, wofür sie da ist: die Dehnungswerte pflegen und nachsehen, welche Werkstoffe es gibt. Neu anlegen geht ab jetzt an beiden Orten."],
 "3.181":["<b>Die App schlägt vor, welche Katalogpositionen Blech sind.</b> Im Materialbestand steht jetzt eine aufklappbare Liste: <i>„42 Katalogpositionen sehen nach Blech aus, werden aber nicht geführt“</i>. Erkannt wird an der Einheit <b>m²</b> zusammen mit einer blossen Zahl bei „Dim.“ – das gibt es praktisch nur bei Blech, und die Zahl ist dort die Stärke.",
  "Jede Zeile bringt die <b>Stärke schon mit</b>, aus „Dim.“ übernommen. Zu wählen bleiben Werkstoff, Ausführung und Rolle/Tafel – ein Klick auf <b>„Als Blech führen“</b>, und die Position ist geführt. Kein Dialog, keine EDV-Nr. abtippen.",
  "<b>Rolle oder Tafel wird nicht geraten.</b> Das steht nirgends in den Daten, und eine Vermutung würde den Zuschnitt falsch rechnen. Bei einer <b>Tafel</b> öffnet sich der Dialog, weil dort noch Länge und Breite fehlen – halb angelegt wird nichts.",
  "Klebebänder, Schellen und Schrauben fallen von selbst heraus (Einheit Stk/m1, oder „Dim.“ wie 20x3). Es muss keine Namensliste gepflegt werden."],
 "3.182":["<b>Behoben: Einstellungen wurden still nicht gespeichert.</b> Die Felder in den Katalogen – Leistungen, Material, Profile, Blitzschutz-Material und die Werkstoffe mit ihren Dehnungswerten – schrieben die Änderung gar nicht zur Datenbank. Die App meldete keinen Fehler, der neue Wert stand weiterhin im Feld, und nach dem nächsten Neuladen war er wieder weg. Das betraf jedes Feld, das ohne eigenen Speichern-Knopf direkt in der Liste geändert wird.",
  "Jetzt wird geschrieben und das Ergebnis <b>bestätigt</b>: unten erscheint kurz <i>„✓ Gespeichert.“</i>. Geht es nicht durch – etwa weil die Berechtigung fehlt – steht dort stattdessen, was schiefging, und der Hinweis bleibt länger stehen. Stilles Verschlucken gibt es nicht mehr.",
  "<b>Der Werkstoff wird beim Nachtragen vorgeschlagen.</b> In der Liste „sieht nach Blech aus“ liest die App den Werkstoff aus dem Positionstext: „Kupferblech 0.6mm“ wird zu Kupfer, „Alublech“ zu Aluminium. Der Vorschlag ist vorausgewählt und kann geändert werden.",
  "Verglichen wird dabei mit <b>Ihrer eigenen Werkstoff-Liste</b>, nicht mit einer fest eingebauten Tabelle – ein neu angelegter Werkstoff wird sofort miterkannt. Nur der Wortanfang zählt: „Chromnickelstahl 1.4301“ wird deshalb <b>nicht</b> als Stahl vorgeschlagen, denn das ist es nicht. Passt kein Wort eindeutig, bleibt die Auswahl leer statt falsch."],
 "3.183":["<b>Ein geführter Start für neue Firmen.</b> Wer die App frisch bekommt, findet leere Auswahlfelder vor: keinen Material-Katalog, keine Werkstoffe, keine Rollenbreiten – und bisher sagte die App dazu nichts. Jetzt steht zuoberst auf der Startseite eine Karte <i>„Ihre Einrichtung – 3 von 7 nötigen Angaben erledigt“</i>.",
  "Jeder Punkt sagt, <b>warum</b> er nötig ist – „ohne Ansatz bleibt im Regierapport die Spalte mit dem Betrag leer“ – und öffnet mit einem Tippen die <b>bestehende</b> Karte in den Einstellungen. Es gibt kein zweites Formular, in das man an der gewohnten Stelle vorbei tippen könnte.",
  "<b>Der Haken wird nicht gespeichert, sondern abgeleitet</b> – er kommt aus denselben Daten, mit denen die App ohnehin rechnet. Wird ein Katalog später wieder geleert, meldet sich der Punkt von selbst zurück. Eine gemerkte Marke könnte „erledigt“ behaupten, während die Liste leer ist.",
  "Ist alles erfasst, verschwindet die Karte. Über <b>Mehr → Einrichtung prüfen</b> lässt sie sich jederzeit wieder ansehen. Sichtbar ist sie nur für Administratoren – die Punkte führen alle in Bereiche, die ohnehin nur sie ändern dürfen."],
 "3.184":["<b>Eine neue Firma startet nicht mehr bei null.</b> Bei der Registrierung bekommt sie die <b>sechs Werkstoffe samt Dehnungswerten</b>, die <b>Rollenbreiten</b> 1000/670/330/250, die <b>MwSt</b> und die <b>sieben Rinne-Ansetztypen</b> mit. Das ist Materialphysik und Branchenstandard, keine Betriebsdaten – jeder Wert bleibt änderbar.",
  "Dazu kommen <b>acht Beispiel-Positionen</b> im Katalog, vier davon fertig eingerichtete Bleche. Damit lassen sich Regierapport, Lager und Zuschnitt vom ersten Moment an ausprobieren, ohne erst eine Lieferantenliste zu besorgen.",
  "<b>Sie tragen ausdrücklich keinen Preis</b> (0.00). Ein erfundener Preis, der unbemerkt in einen echten Rapport läuft, wäre schlimmer als gar keiner – niemand kontrolliert einen Wert, der schon dasteht. Und sie zählen in der Einrichtungs-Checkliste <b>nicht mit</b>: dort steht „0 eigene Positionen (dazu 8 Beispiele)“.",
  "<b>Sie lösen sich von selbst auf</b>, sobald der Betrieb seine erste eigene Position anlegt oder eine Excel-Liste importiert. Unbenutzte verschwinden ohne Rückfrage.",
  "<b>Wurde eine Beispiel-Position schon benutzt</b>, entscheidet der Firmenadmin – die App löscht da nichts von selbst. Vier Wege: <i>Alles behalten</i> (nur der Vermerk geht weg, nichts geht verloren), <i>Ersetzen</i> (alles, was darauf zeigt, zeigt danach auf eine echte Position – erst danach wird gelöscht), <i>Löschen</i> (die Rückfrage nennt jede Position samt dem, was daran hängt) und <i>Später entscheiden</i>."],
 "3.185":["<b>Aufgaben lassen sich auf ein Datum terminieren.</b> An jeder Aufgabe steht <b>🗓 Terminieren</b>. Ein Datum gewählt, und sie verschwindet aus der Liste, bis dieser Tag da ist – für Ferien, oder wenn die Montage erst in einem Monat stattfindet.",
  "<b>Nichts verschwindet lautlos.</b> Über der Liste steht <i>„2 terminiert – anzeigen“</i>. Ein Tippen blendet sie wieder ein, mit dem Datum an jeder Karte und einem Knopf <b>Termin aufheben</b>. Ist nichts terminiert, steht dort auch keine Zeile.",
  "<b>Der Termin gilt für einen Schritt</b>, nicht für die ganze Massaufnahme. Wer das Rüsten auf nächste Woche legt, verschiebt damit nicht auch das Montieren – das sind zwei Arbeiten, oft von zwei verschiedenen Leuten. Und er gilt nur für <b>Ihre eigene</b> Liste: ein Termin des Rüsters ändert nichts an der Liste des Monteurs.",
  "<b>Am Ablauf ändert sich nichts.</b> Im Projekt, in der Werkstatt und in der Übersicht der Firmenleitung bleibt die Massaufnahme unverändert sichtbar. Ein Termin ist kein Weg, Arbeit verschwinden zu lassen – er räumt nur die eigene Startseite auf.",
  "Ist der Tag erreicht, ist die Aufgabe von selbst wieder da. Ein Termin auf heute oder in der Vergangenheit wird abgewiesen – er würde nichts ändern."],
 "3.186":["<b>Die App kontrolliert jetzt die eigenen Stammdaten.</b> Unter <b>Einstellungen → Allgemein → Kontrolle der Stammdaten</b> steht, was erfasst ist, aber nicht stimmt. Die Einrichtungs-Checkliste fragt, <i>ob</i> etwas da ist – diese Liste fragt, ob es auch <i>stimmt</i>.",
  "<b>Acht Prüfungen in vier Gruppen.</b> Blech ohne Werkstoff, Werkstoff ohne Dehnungswerte, Tafel ohne Länge oder Breite · Katalogposition ohne Einheit, Position mit Preis 0.00 · zwei Bleche mit denselben Merkmalen · und das Verwaiste: Reststück unter dem eigenen Mindestmass, Werkstoff ohne ein einziges Blech, Katalogposition, die nie vorkam.",
  "<b>Rot heisst: die App rechnet hier nicht.</b> Ein Blech ohne Werkstoff bekommt keine Dilatation, eine Tafel ohne Format keinen Zuschnittplan. Blau ist ein Hinweis – es funktioniert, sieht aber nach einem Versehen aus. Nur bei rot erscheint eine Karte auf der Startseite; Hinweise belegen sie nicht.",
  "<b>Manches ist Absicht.</b> Eine Position mit Preis 0.00 kann eine Beistellung sein. Der Knopf <i>„ist so gewollt“</i> hakt genau diese eine Position ab – sie zählt nicht mehr mit, bleibt aber unter <i>„x abgehakt – anzeigen“</i> sichtbar und lässt sich jederzeit wieder melden.",
  "<b>Nichts wird gespeichert ausser dem Abhaken.</b> Der Befund selbst wird jedes Mal neu aus den echten Daten gerechnet; verschwindet die Ursache, verschwindet die Meldung, ohne dass jemand etwas quittiert. Und jeder Punkt öffnet die <b>bestehende</b> Karte, in der sich das Feld ändern lässt – kein zweites Formular.",
  "Zwei Dinge werden ausdrücklich <b>nicht</b> geprüft: Produkte ohne Barcode (das träfe fast jede Zeile und wäre Rauschen statt Kontrolle) und doppelte EDV-Nummern (die lässt die Datenbank gar nicht erst zu)."],
 "3.187":["<b>Zwischen zwei Konten wechseln, ohne sich neu anzumelden.</b> Oben rechts steht <b>🔄 Konto wechseln</b>, in der neuen Ansicht unter <b>Mehr → Konto wechseln</b>. Gemeint ist der Fall „eigene Firma und Testfirma“ – bisher hiess das jedes Mal abmelden, Benutzername, Passwort.",
  "<b>Die Rechte bleiben, wie sie sind.</b> Es sind zwei getrennte Anmeldungen, beide auf diesem Gerät gespeichert; der Wechsel tauscht nur aus, welche gerade gilt. An der Datenbank ändert sich <b>nichts</b> – kein Feld, keine Regel. Für den Server ist ein Wechsel dasselbe wie eine neue Anmeldung.",
  "<b>Die App lädt beim Wechsel neu.</b> Absicht: so bleibt garantiert nichts aus der einen Firma in der anderen stehen – keine Liste, keine Zahl, kein Zwischenspeicher.",
  "<b>Zwei Fälle, in denen nicht gewechselt wird</b>, jeweils mit Begründung auf dem Bildschirm: ohne Verbindung (die andere Firma hätte keine Daten), und solange etwas auf die Übertragung wartet – das gehört zur jetzigen Firma und ginge verloren.",
  "<b>Ein gemerktes Konto öffnet sich auf diesem Gerät ohne Passwort.</b> Auf einem persönlichen Arbeitsgerät ist das der Zweck; auf einem geteilten gehört es mit <b>entfernen</b> wieder weg. Das wirkt nur auf diesem Gerät – das Konto selbst bleibt unangetastet."],
 "3.188":["<b>Neu: der Abwicklungsrechner.</b> 📐 Abwicklung auf dem Startbildschirm, in der neuen Ansicht unter <b>Mehr</b>. Er rechnet den Zuschnitt für ein rundes Blechrohr mit schrägem Anschnitt, angebogenem Schweifbord und liegendem Längsfalz – die Rechnung, die bisher nur als Fusion-360-Script ausserhalb der App lief.",
  "<b>Dieselbe Rechnung, nicht eine neue.</b> Das Script ist Zeile für Zeile nach JavaScript übertragen, nicht nachgebaut: ein Schweifbord ist geometrisch nicht abwickelbar, und eine eigene Näherung wäre eine zweite Wahrheit neben der, nach der in der Werkstatt bisher geschnitten wurde. Die sieben Kontrollwerte des Auftrags trifft sie exakt (Umfang 343,38 · Zuschnittbreite 361,38 · Höhe 371,25/305,17 · Schweifbord-Zugabe 37,13…40,10 · Biegewinkel 60…120° · Streckung 67 %).",
  "<b>Massstäbliche Vorschau</b>, während Sie tippen: Zuschnitt durchgezogen, Biegelinie des Schweifbords rot gestrichelt, Falz blau, die Einschnitte für die Lappen dünn. Darunter die Tabelle mit allen Kennzahlen.",
  "<b>Ausgeben als DXF</b> (mit den Layern ZUSCHNITT, BIEGELINIE_KRAGEN, BIEGELINIE_FALZ, EINSCHNITT), als <b>SVG 1:1</b> oder als <b>Schablone auf A4</b> – aufgeteilt mit Überlappung, Passmarken und Seitennummern. Auf jedem Blatt steht ein <b>100-mm-Kontrollmass</b>: einmal nachmessen, denn eine um vier Prozent verkleinerte Schablone fällt sonst erst am Blech auf.",
  "<b>Speichern beim Projekt</b>, laden, duplizieren, löschen. Gespeichert werden die <b>Masse</b>, nicht die gezeichnete Kontur – die wird beim Laden neu gerechnet. Weicht das Ergebnis vom gespeicherten ab, sagt die App es ausdrücklich, statt stillschweigend andere Zahlen zu zeigen.",
  "<b>Die App warnt, wo es fachlich klemmt:</b> wenn die Schweifbord-Zugabe für die Krümmung zu gross wird, und wenn der Rand über rund 10 % gestreckt würde und keine Lappen gesetzt sind – von Hand aufziehen geht dann nicht mehr."],
 "3.189":["<b>Das Teil heisst jetzt überall Schweifbord</b>, nicht mehr „Kragen“ – im Formular, in der Vorschau, in der Ergebnistabelle, in der Hilfe und in der Anleitung. Auch der DXF-Layer heisst neu <i>BIEGELINIE_SCHWEIFBORD</i>.",
  "<b>Die Vorgabe ist 0 Lappen</b> statt 24: im Betrieb wird das Bord nachher auf der Maschine geschweift, Einschnitte sind die Ausnahme. Ohne Lappen steht im DXF auch kein leerer Layer <i>EINSCHNITT</i> mehr.",
  "<b>Die Streckungs-Warnung schreibt nichts mehr vor.</b> Sie sagte „bitte Lappen verwenden“; jetzt heisst es „von Hand aufziehen geht so nicht – entweder schweifen oder Lappen einschneiden“. Eine Meldung, die den eigenen Arbeitsweg nicht kennt, wird überlesen.",
  "<b>Neu erklärt: warum die Zugabe am Zuschnitt nicht überall gleich breit war.</b> Beim schrägen Anschnitt biegt das Bord auf der langen Seite nur um 60°, auf der kurzen um 120°. Eine schärfere Biegung frisst mehr Material im Radius, also brauchte der flache Zuschnitt dort weniger. Mit v3.190 ist das umgestellt – siehe unten."],
 "3.190":["<b>Die Zugabe am Schweifbord ist jetzt über den ganzen Zuschnitt gleich.</b> Gerechnet wird sie mit 90°, bei den Standardmassen <b>39,34 mm</b> statt bisher 37,13 bis 40,10. Ein Streifen, der über die Länge um 3 mm schwankt, lässt sich nicht anreissen – und geschweift wird nachher ohnehin, dabei wandert das Material.",
  "<b>Was das kostet, steht jetzt in der Tabelle.</b> Neue Zeile <b>Bord fertig (rechnerisch)</b>: mit einer konstanten Zugabe wird das fertige Bord nicht überall exakt so breit wie eingegeben – bei den Standardmassen 39,2 bis 42,2 mm statt 40. Beim senkrechten Schnitt (α = 0) stimmt es weiterhin exakt.",
  "<b>Drei Zahlen ändern sich dadurch:</b> Höhe an der Naht 370,49 statt 371,25 mm, Höhe min 307,39 statt 305,17 mm, Streckung 68,5 statt 67 %. Umfang (343,38), Zuschnittbreite (361,38) und Biegewinkel (60…120°) bleiben unverändert.",
  "<b>Eine vor v3.190 gespeicherte Abwicklung sagt es beim Laden.</b> Die App vergleicht die gespeicherte Zuschnittbreite <i>und</i> die Höhe mit der frisch gerechneten und meldet jede Abweichung im Klartext – ein Zuschnitt, nach dem schon geschnitten wurde, bekommt nicht stillschweigend andere Zahlen.",
  "Das Fusion-360-Script rechnet weiterhin die alten Werte. Das ist kein Fehler, sondern der Entscheid – so steht es auch im Quelltext und in Kapitel 26 der Anleitung."],
 "3.191":["<b>Die Einfassung rund reicht ihre Masse an den Abwicklungsrechner weiter.</b> Bei jeder Einfassung steht neu <b>⭕ Abwicklung Rohr</b>. Damit kommen <b>Ø Standrohr</b>, der <b>Winkel Dach/Rohr</b> und die <b>Materialstärke</b> der Massaufnahme herüber, dazu das Projekt und ein Vorschlag für die Bezeichnung.",
  "<b>Das gehört fachlich zusammen.</b> Die Einfassung rund rechnet den Querschnitt (a, b, c) und lässt das Rohr selbst ausdrücklich offen – „das Rohr wird nicht als Abwicklung um sich selbst modelliert“. Genau dieses Rohr rechnet die Abwicklung. Die beiden ergänzen sich, sie überschneiden sich nicht.",
  "<b>Der Winkel wird nicht doppelt umgerechnet.</b> Angezeigt wird der Winkel Dach/Rohr (Dachneigung + 90, auf einem 25°-Dach also 115°), gespeichert die Dachneigung – und genau die ist der Schnittwinkel der Abwicklung. Der Prüfstand rechnet das von Hand nach; es wäre der teuerste Fehler, den diese Brücke machen könnte.",
  "<b>Rohrhöhe und Schweifbord-Breite</b> gibt es in der Einfassung nicht – es sind Werkstattstandards, keine Masse vom Dach. Sie stehen neu als Richtwert unter <b>Einstellungen → Massaufnahmen → Einfassung Rund</b> und fliessen mit. Eine <b>0</b> heisst dort „nicht gesetzt“: dann bleibt in der Abwicklung der Wert stehen, der dort schon steht. Es wird nichts erfunden.",
  "<b>Oben in der Abwicklung steht, was übernommen wurde – und was nicht.</b> Die nicht übernommenen Felder sind genau die, die Sie noch prüfen müssen. Eine Übernahme, die nur ihre Treffer meldet, lässt Sie raten.",
  "<b>Gespeichert gehört die Abwicklung danach zu genau dieser Massaufnahme</b>, nicht nur zum Projekt – sonst weiss später niemand mehr, zu welchem Rohr der Zuschnitt war. Mit <b>Verbindung lösen</b> oder <b>Standardmasse</b> ist der Bezug wieder weg."],
 "3.192":["<b>Neu: das Tablett der Einfassung rund wird abgewickelt – samt Lochausschnitt.</b> Der Abwicklungsrechner kennt jetzt zwei <b>Bauteile</b>: das Rundrohr wie bisher und das flache Blech auf dem Dach, durch das das Rohr steigt. Vorschau, Ergebnis, DXF, 1:1-Schablone und die gespeicherte Liste sind für beide dieselben.",
  "<b>Das Loch ist eine Ellipse, kein Kreis.</b> Das Tablett liegt in der Dachfläche, das Rohr steht im Lot – ein senkrechtes Rohr durch eine geneigte Ebene ergibt eine Ellipse: quer zum Gefälle so breit wie das Rohr, in Gefällerichtung um 1/cos α länger. Bei Ø 110 und 30° Dachneigung sind das 110 × 127 mm; ein rundes Loch wäre 17 mm zu kurz.",
  "<b>Die Luft am Lochausschnitt ist einstellbar.</b> Gerechnet wird der Schnitt eines gedachten Rohrs mit Ø + 2 × Zugabe – so wächst die Luft in Gefällerichtung genauso mit, wie das Rohr nachher im Loch steht. Der Richtwert steht unter <b>Einstellungen → Massaufnahmen → Einfassung Rund</b>; <b>0</b> ist dort gültig und heisst „Loch exakt auf Rohrmass“.",
  "<b>Die Zuschnittlänge ist dieselbe Zahl wie in der Massaufnahme.</b> Umschlag + Anreiss + a + b + c + Umschlag – genau das, was die Einfassung rund als „Zuschnittbreite (Querschnitt)“ ausgibt. Der Prüfstand rechnet beide gegeneinander, damit es nie zwei Längen für dasselbe Blech gibt.",
  "<b>Der Weg geht jetzt in beide Richtungen.</b> In der Massaufnahme stehen bei jeder Einfassung <b>⭕ Abwicklung Rohr</b> und <b>▭ Abwicklung Tablett</b>. Umgekehrt holt im Rechner <b>📥 Masse aus einer Massaufnahme holen</b> die Masse aus einer bereits gespeicherten Aufnahme – die Materialstärke kommt dabei aus dem gespeicherten Datensatz, nicht aus einem zufällig offenen Formular."],
 "3.193":["<b>Behoben: die Schablone lief über den Blattrand hinaus.</b> Ein Blatt war 280,9 mm hoch, auf A4 mit 8 mm Rand sind 281,0 mm Platz – 0,1 mm Reserve. Sobald der Drucker auf Standardränder stand, rutschte der untere Teil auf eine zusätzliche, halbleere Seite. Kopf- und Fusszeile sind jetzt einzeilig, und für sie sind 24 statt 12 mm reserviert: neu bleiben auf jedem Format über 15 mm Reserve.",
  "<b>Neu: die App schlägt das Papierformat vor.</b> Sie rechnet A4, A3, A2 und A1 in beiden Lagen durch und wählt das Format mit den wenigsten Blättern. Bisher war A4 fest verdrahtet – das Tablett brauchte damit sechs Blatt, und beim Rohr trug die dritte Spalte 1,4 mm Zeichnung, also ein ganzes Blatt für nichts.",
  "<b>Bei jedem Format steht, wie viele Blätter es wären.</b> „A4 hoch · 6 Blatt“, „A3 quer · 3 Blatt“, „A1 hoch · 1 Blatt“ – man sieht sofort, was grösseres Papier spart, und kann jederzeit umstellen. Bei gleicher Blattzahl gewinnt das kleinere Papier, sonst ginge jeder kleine Zuschnitt zum Plotter.",
  "<b>Der Drucker erfährt das Format jetzt auch.</b> Die Schablone sagt ihm die Blattgrösse in Millimetern mit, samt Lage – ohne das hätte er eine A2-Schablone weiterhin auf A4 abgeschnitten. <b>A0</b> steht nicht zur Wahl, weil es im Betrieb nicht gedruckt werden kann."],
 "3.194":["<b>Das flache Blech auf dem Dach heisst jetzt „Tablett“</b> – in v3.192 und v3.193 stand dort noch „Hablett“. Umbenannt ist es überall: Auswahl, Knopf in der Massaufnahme, Ergebnis, Hilfe, Anleitung und Datenbank.",
  "<b>Eine vorher gespeicherte Abwicklung geht unverändert auf.</b> Datensätze aus v3.192 und v3.193 tragen intern noch den alten Namen; sie werden weiterhin als Tablett geöffnet und gerechnet. Sie als Rohr zu öffnen wäre das Schlimmste, was hier passieren könnte – die Zahlen bedeuten bei den beiden Bauteilen etwas völlig anderes."],
 "3.195":["<b>Das Standardmass für das Schweifbord ist neu 12 mm</b> statt 40. Die 40 kam aus dem Fusion-360-Script, nicht aus dem Betrieb.",
  "<b>Das schmale Bord wird viel weniger gestreckt:</b> 21 % statt 68,5 %. Gestreckt wird es weiterhin, die App sagt es auch – aber der Unterschied ist erheblich.",
  "<b>Was sich dadurch ändert:</b> Zugabe 11,34 statt 39,34 mm, Höhe 342,49 bis 279,39 statt 370,49 bis 307,39 mm, Bord fertig 11,2 bis 14,2 statt 39,2 bis 42,2 mm. Umfang (343,38), Zuschnittbreite (361,38) und Biegewinkel (60…120°) bleiben unverändert – sie hängen nicht an der Bordbreite.",
  "<b>Die Zahlen in den Einträgen zu v3.190 gelten weiter für das damalige Standardmass von 40 mm.</b> Sie sind das Protokoll dessen, was damals geändert wurde, und werden deshalb nicht umgeschrieben.",
  "Eine gespeicherte Abwicklung behält ihre eigene Bordbreite. Das Standardmass gilt nur für eine neue."],
 "3.196":["<b>Die Lappeneinschnitte sind weg.</b> Sie entsprechen nicht mehr dem Stand der Technik – geschweift wird auf der Maschine. Damit fällt auch der Hinweis weg, der früher bei 0 Lappen kam („entweder schweifen oder Lappen einschneiden“): er kam bei jeder Rechnung und sagte nichts, was der Betrieb nicht ohnehin tut. Die <b>Streckung</b> wird weiterhin gerechnet und steht in der Ergebnistabelle – nur eben als Zahl, nicht als Warnung.",
  "<b>Der Dachwinkel steht nur noch einmal da.</b> Beim Rohr hiess er „Schnittwinkel“, beim Tablett „Dachwinkel“ – es ist dasselbe Mass, und man musste es zweimal eintippen. Jetzt gibt es <b>ein</b> Feld für beide Bauteile. Wer dasselbe Mass zweimal erfasst, hat früher oder später zwei verschiedene Winkel für dasselbe Dach.",
  "<b>Das Standardmass für die Falzbreite ist neu 5 mm</b> statt 6. Die Zuschnittbreite wird damit 358,38 statt 361,38 mm.",
  "Eine vor v3.196 gespeicherte Abwicklung mit Lappen öffnet unverändert – die Angabe wird beim Rechnen einfach übergangen, der Zuschnitt bleibt derselbe."],
 "3.197":["<b>Auch der Rohrdurchmesser steht jetzt nur noch einmal da.</b> Zusammen mit der Dachneigung aus v3.196 heisst das: die Masse, die bei Rohr und Tablett dieselben sind, werden einmal erfasst und gelten für beide.",
  "<b>Nicht zusammengelegt ist b</b> – beim Rohr ist das die Schweifbord-Breite, beim Tablett das Mass von Mitte Rohr nach hinten. Derselbe Buchstabe, zwei völlig verschiedene Masse. Sie bleiben getrennt, und der Prüfstand hält das ausdrücklich fest."],
 "3.198":["<b>Behoben: „permission denied for function mw_firma_ok“ beim Terminieren einer Aufgabe.</b> Die Prüffunktion hinter den Zugriffsregeln der Aufgaben-Termine hatte für angemeldete Nutzer nie ein Ausführungsrecht bekommen – ein Fehler von v3.185. Betroffen waren alle vier Wege (lesen, anlegen, ändern, löschen), das Terminieren hat also noch nie funktioniert. Behoben in der Datenbank; ohne App-Update wirksam.",
  "<b>Werkstoffe ohne Dehnungswerte lassen sich jetzt als „ist so gewollt“ abhaken.</b> Bei einem Werkstoff, der gar nicht dilatiert wird – Blei zum Beispiel –, sind fehlende Dehnungswerte richtig. Bisher blieb so ein Eintrag dauerhaft als roter Fehler stehen, und eine Meldung, die sich nicht erledigen lässt, verdeckt nach einer Weile die, die es ernst meinen.",
  "Abgehakt wird dabei der <b>einzelne Werkstoff</b>, nicht die Prüfung: ein später angelegter Werkstoff ohne Dehnungswerte meldet sich wieder."],
 "3.199":["<b>Offertpositionen aus den Katalogen.</b> Zuerst am Import-Formular gebaut – mit v3.200 dorthin gezogen, wo sie hingehören: in die neue Funktion „Offerte erstellen“."],
 "3.200":["<b>Neu: eine eigene Offerte für den Kunden schreiben.</b> Im Projekt gibt es dafür die Karte „🧾 Offerte erstellen“: Kunde, Positionen aus deinen Katalogen (Stundenansätze und Regiematerial), Rabatt, MwSt, Vor- und Schlusstext – und daraus ein <b>PDF zum Verschicken</b>, das sich gleich beim Projekt ablegen lässt.",
  "<b>Die bisherige Offertfunktion heisst jetzt „📥 Offerte importieren“</b> und bleibt unverändert. Sie ist für den umgekehrten Fall: eine bestehende, fremde Offerte einlesen und daraus die Massaufnahmen ableiten. Zwei verschiedene Vorgänge, zwei Karten – dieselbe Freigabe.",
  "Briefkopf, Adresse, Logo und MwSt-Satz kommen aus den Einstellungen; dort stehen neu auch <b>Vortext, Schlusstext und Gültigkeitsdauer</b> als Vorgabe für neue Offerten.",
  "Was du in der Vorschau siehst, ist das PDF selbst – nicht eine nachgebaute Ansicht. Was dort steht, bekommt der Kunde."],
 "3.201":["<b>„Offerte erstellen“ ist jetzt auch in der neuen Ansicht da</b> – auf der Projektseite unter „Mehr“, zuoberst, noch vor dem Import. Vorher gab es sie nur im alten Cockpit.",
  "<b>EDV-Nr. tippen genügt.</b> Wer in der Positionsliste eine Nummer ins Feld „Pos.“ tippt, sieht sofort die passenden Materialpositionen; ein Klick übernimmt Bezeichnung, Einheit und Preis.",
  "Von Hand geht weiterhin alles: eine Nummer ohne Treffer bleibt stehen, und ohne Klick wird nie etwas überschrieben."],
 "3.203":["<b>Die Navigation der neuen Ansicht ist aufgeräumt.</b> Im Projekt gibt es keinen Sammelpunkt „Mehr …“ mehr – Offerte und Dateien haben eigene Register, und jedes ist einen Griff entfernt.",
  "<b>Die Ablaufkette ist jetzt anklickbar.</b> Ein Tipp auf „Offerte“, „Rüsten“ oder „Ausmass“ führt direkt ins zugehörige Register. Kette und Register sind dieselbe Landkarte statt zwei verschiedener.",
  "<b>Zwei Namen sind genauer:</b> das Projekt-Register heisst „Rüsten & Montage“ (die „Werkstatt“ unten in der Leiste ist die der ganzen Firma), und aus „Produktion“ wurde „Material“.",
  "Das Dateien-Register zeigt die Dateien jetzt mit Namen, Datum und Grösse, statt nur die alte Projektansicht zu öffnen. Und die Seite „Mehr“ ist in Arbeiten, Firma und Verwaltung gegliedert."],
 "3.202":["<b>Behoben: „Vortext und Schlusstext“ liessen sich in der neuen Offerte nicht öffnen.</b> Der Block war zugeklappt, und ein Klick auf die Überschrift tat nichts – der Text war da, aber unerreichbar. Ein Fehler von v3.200: den vier Blöcken des Formulars fehlte der Klapp-Handler ganz. Jetzt lässt sich jeder öffnen und schliessen, auch mit der Tastatur."],
 "3.204":["<b>„Material“ und „Rüsten &amp; Montage“ sind ein Register geworden: „Herstellung“.</b> Es zeigt den ganzen Weg von der Massaufnahme zum fertigen Teil auf einer Seite – erst Material &amp; Zuschnitt, dann Rüsten &amp; Montieren –, und über jedem Abschnitt steht ein Satz, wofür er da ist. Vorher zeigten beide Register dieselben Massaufnahmen, nur anders geordnet.",
  "Neue Regel auf der Projektseite: ein <b>blauer</b> Knopf bleibt im Projekt, ein <b>grauer</b> führt hinaus. „Werkstatt aller Projekte öffnen“ ist deshalb grau und steht zuunterst.",
  "Register „Dateien“: statt vier Zeilen, die alle am selben Ort endeten, steht jetzt die Dateiliste und darunter ein beschrifteter Knopf.",
  "Fehler behoben: beim Öffnen von „Dateien, Fotos und Verlauf“ war kurz die ganze alte Projektansicht zu sehen, bevor sie sich auf das Gesuchte einschränkte."],
 "3.205":["<b>Die App startet jetzt auch ohne Verbindung zuverlässig.</b> Drei Fremdbibliotheken kamen bisher bei jedem Start von einem fremden Server – darunter die, ohne die die App überhaupt nicht hochfährt. Der Offline-Vorrat konnte sie gar nicht aufheben; ob es ohne Netz ging, war Zufall. Jetzt liegen alle drei in der App selbst.",
  "Die App startet spürbar schneller: 860 kB Excel-Bibliothek werden nicht mehr bei jedem Start geladen, sondern erst, wenn man Excel wirklich braucht.",
  "Der Barcode-Scan funktioniert jetzt auch im Keller ohne Empfang – vorher hiess es dort „Internetverbindung prüfen“.",
  "Datenbank: fünf interne Funktionen waren ohne Anmeldung aufrufbar. Das ist zurückgenommen – sie waren zwar innen abgesichert, aber es gab keinen Grund, sie offen zu lassen."],
 "3.206":["<b>Datenbank: die Zugriffsregeln prüfen jetzt einmal je Abfrage statt einmal je Zeile.</b> Bei 25 Regeln wurde die Anmeldung für jede einzelne geprüfte Zeile neu nachgeschlagen. Am Inhalt der Regeln ändert sich nichts – nur daran, wie oft gerechnet wird.",
  "<b>Eine Lücke geschlossen:</b> beim Abwicklungsrechner war die Firmengrenze versehentlich als <i>zusätzliche Erlaubnis</i> statt als <i>Schranke</i> gesetzt – als einzige von 35. Wer das Recht „Material ansehen“ hatte, hätte damit an die Abwicklungen anderer Firmen gekommen. Die Tabelle war zu diesem Zeitpunkt leer, es ist also nichts abgeflossen."],
 "3.207":["<b>Eine Aufgabe, deren Termin abgelaufen ist, lässt sich wieder terminieren.</b> Das Datumsfeld war mit dem alten, bereits verstrichenen Datum vorbelegt – wer nur auf Speichern tippte, bekam „Das Datum muss in der Zukunft liegen“ und nichts geschah. Jetzt steht dort ein Datum, das sich auch speichern lässt.",
  "<b>Die Kontrolle der Stammdaten meldet auf der Startseite nichts mehr, was längst als „ist so gewollt“ abgehakt ist.</b> Die Karte wurde gezeichnet, bevor die Abhaken-Entscheidungen überhaupt gelesen waren, und zählte sie deshalb bei jedem App-Start wieder als Fehler."],
 "3.208":["<b>Die Materialliste lässt sich als Excel-Datei herausgeben.</b> Einstellungen → Firma → Material (Regierapport) → „Als Excel exportieren“. Die ersten fünf Spalten sind genau die, die der Import wieder einliest – herunterladen, in Excel ändern, wieder importieren.",
  "<b>Messing und Blei gehören jetzt zu den Werkstoffen, die jede neue Firma mitbekommt.</b> Beide ohne Dehnungswerte – sie werden nicht dilatiert – und deshalb gleich als „ist so gewollt“ abgehakt, damit die Kontrolle der Stammdaten am ersten Tag nicht zwei Fehler meldet.",
  "Das leere Register „Ausmass“ in den Einstellungen ist weg, und „Geschützt“ heisst jetzt <b>Firma</b> – drin stehen Firma, Mitarbeiter, Stundensätze, die Materialkataloge und die Datensicherung."],
 "3.209":["<b>Die Dachfenstereinfassung hat jetzt auch ein Feld für die Materialstärke.</b> Sie kannte bisher nur den Werkstoff – das Stärkefeld, das alle anderen zwölf Arten seit v3.31 haben, wurde bei ihr nie angehängt. Bereits gespeicherte Dachfenster-Aufnahmen lassen sich einfach öffnen und ergänzen."],
 "3.210":["<b>Das Register in den Einstellungen heisst jetzt „Firma“</b> – für eine Zwischenversion hiess es „Betrieb“. Inhalt unverändert: Firmendaten, Mitarbeiter, Stundensätze, Materialkataloge, Datensicherung.",
  "Die <b>Testfirma</b> hat dieselben acht Werkstoffe hinterlegt wie der Hauptbetrieb – bisher stand dort nur Kupfer."],
 "3.211":["<b>Das Rüstblatt.</b> Ein Tipp auf eine Massaufnahme zeigt jetzt nur noch das Wichtigste: das vermasste Profil, den Grundriss, Material und Stärke und die Zuschnittliste zum Abhaken – statt das ganze Formular zu öffnen. Wer doch etwas ändern will, tippt darin auf „Im Formular öffnen“.",
  "Dasselbe Blatt steht an vier Stellen: Werkstatt nach Projekt, Werkstatt nach Material, Seite „Material &amp; Zuschnitt“ und Projektseite. <b>„Gross ansehen“</b> zeigt es bildschirmfüllend – für die Abkantbank.",
  "<b>Alle Massaufnahmen lassen sich zuklappen</b>, einzeln oder mit einem Schalter über der Liste. In der Werkstatt nach Material und auf der Seite „Material &amp; Zuschnitt“ ging das bisher gar nicht."],
 "3.212":["<b>Eine zugeklappte Massaufnahme in der Werkstatt ist jetzt gleich klein wie auf der Projektseite</b> – zwei Zeilen statt bis zu vier: oben Art und Bezeichnung, unten Status und Zuschnittstand, der Knopf zum Bestätigen schmal daneben. Auf einen Blick sieht man dadurch rund doppelt so viele Aufträge.",
  "Material und Stärke stehen zugeklappt nicht mehr dabei – der Platz gehört der Bezeichnung, nach der ausgewählt wird. Aufgeklappt und im Rüstblatt stehen sie unverändert."],
 "3.213":["<b>In der Werkstatt lässt sich jetzt das ganze Projekt zuklappen.</b> Ein Tipp auf den Projektkopf, und übrig bleiben Objekt, Projekt und die Anzahl dessen, was dort ansteht – „Rüstliste“ und „Projekt“ bleiben erreichbar. Über der Liste stehen zwei Schalter: einer für alle Projekte, einer für alle Massaufnahmen.",
  "<b>Ab vier Projekten startet nur das oberste offen</b> – also das, das laut rotem Faden zuerst drankommt. Bei drei oder weniger bleibt alles offen wie bisher. In der Sicht nach Material gilt dasselbe für die Materialgruppen."],
 "3.214":["<b>Drei Knöpfe unter dem Datumsfeld: In einer Woche, In zwei Wochen, In einem Monat.</b> Das Feld öffnet auf morgen – wer nur speichert, hat die Aufgabe am nächsten Tag wieder vor sich. Die Knöpfe setzen nur das Feld, gespeichert wird wie bisher erst mit „Speichern“."],
 "3.215":["<b>Die Werkstatt öffnet jetzt mit allen Projekten zugeklappt.</b> Sie ist damit zuerst eine Liste der Baustellen; aufgeklappt wird, woran gerade gearbeitet wird. „Jetzt dran“ steht weiterhin über der Liste, und jeder Projektkopf sagt, wie viel dort ansteht – es verschwindet nichts."],
 "3.216":["<b>Behoben: Beim Terminieren wurde das falsche Datum gespeichert.</b> Wer in der neuen Ansicht ein Datum wählte – etwa den 5.10. – bekam stattdessen den Vorschlag „morgen“ gespeichert und hatte die Aufgabe am nächsten Tag wieder vor sich. Ursache: dieselbe Aufgabe steht zweimal auf der Seite (alte Startseiten-Karte und neue Ansicht), und gespeichert wurde das erste Feld statt dem, in das getippt wurde. Jetzt gilt das Datum aus der Karte, die man vor sich hat.",
  "Der Hinweis aus v3.214 („war auf … terminiert“) ist wieder weg – er beantwortete eine Frage, die es gar nicht gab."],
 "3.217":["<b>Suchen in der Werkstatt.</b> Über der Liste steht ein Suchfeld: Objekt, Projekt, Auftrags-Nr., Kunde, Bezeichnung und Art. Mehrere Wörter suchen zusammen; eine reine Zahl muss als ganze Zahl vorkommen, damit „Musterstrasse 3“ nicht jede Adresse mit Postleitzahl 3000 findet."],
 "3.218":["<b>Die alte Ansicht ist weg.</b> Es gibt nur noch eine Oberfläche – die nach dem Arbeitsablauf gegliederte. Die alte Startseite („Was möchtest du tun?“ mit den grossen Knöpfen), die Aufgabenkarte darüber, die Zeile „Angemeldet als …“ und der Umschalter dazu sind entfallen.",
  "Alles davon ist weiterhin erreichbar: Projekte und Werkstatt über die Leiste unten, Suche, Einstellungen, Feedback, Abwicklung, Anleitung, Konto wechseln, „Was die App gelernt hat“, „Alle Massaufnahmen“ und die System-Administration über <b>Mehr</b>.",
  "Wer auf einem Gerät irgendwann „lieber die gewohnte Ansicht“ eingestellt hatte, startet jetzt trotzdem normal – der gemerkte Wunsch wird nicht mehr gelesen. Die Einstellung „Aufgaben auf dem Startbildschirm zugeklappt/geöffnet“ ist mit der Karte entfallen; in der Ansicht steht die Liste offen da."],
 "3.219":["<b>Behoben: „Fehler (unerledigt): Cannot set properties of null“ beim Öffnen.</b> Nach der Umstellung auf 3.218 kam auf einem Gerät diese Meldung, und die Anmeldung ging nicht mehr. Der Fehler lag nicht in 3.218 selbst, sondern in einer <i>gemischten</i> App-Hülle: die neue Startseite zusammen mit einer alten Programmdatei aus dem Zwischenspeicher.",
  "Ursache: Fehlte beim Aktualisieren eine einzelne Datei (wackliges Netz), suchte der Offline-Speicher sie in <i>allen</i> Fassungen – und lieferte sie aus der alten. Jetzt wird nur noch in der Fassung gesucht, die gerade läuft. Eine Datei, die dort fehlt, gilt als nicht verfügbar, statt aus einer anderen Version zu kommen.",
  "Ausserdem: Eine fehlende Programmdatei bekam bisher die Startseite als HTML geliefert, die der Browser dann auszuführen versuchte. Das gilt jetzt nur noch für den Seitenaufruf selbst."],
 "3.220":["<b>Der Barcode wird im laufenden Bild erkannt.</b> Einscannen/Ausscannen öffnen die Kamera, der Code wird gelesen, sobald er im Rahmen ist – kein Foto mehr aufnehmen und auswerten lassen. Unscharf? Kurz aufs Bild tippen. Der Weg über die Kamera-App des Geräts bleibt als Knopf für den Fall, dass ein Code partout nicht scharf wird; von Hand eintippen geht unverändert.",
  "<b>Die Lagerverwaltung sieht aus wie ein Lager, nicht wie eine Einstellungsseite.</b> Oben der Stand in einer Zeile (Positionen, Produkte und – rot – wie viele ohne Bestand), darunter das Suchfeld, dann die Knöpfe als Leiste statt als Wand. In der Liste steht die EDV-Nr. als Nummernfeld vorn und der Bestand rechts als Zahl mit Einheit, bei 0 rot.",
  "Gerechnet, gebucht und gesucht wird dabei genau wie vorher – geändert ist nur die Darstellung."],
 "3.221":["<b>Behoben: das Kamerabild wurde beim Tippen kurz schwarz.</b> Gemeldet nach 3.220. Das Tippen aufs Bild stammte noch aus der Zeit, als das laufende Bild nur eine Vorschau vor einer Fotoaufnahme war: es schaltete die Kamera ganz ab, holte einen neuen Stream für ein Foto und danach noch einen für die Vorschau – rund anderthalb Sekunden ohne Bild. Jetzt wird der Stream beim Tippen gar nicht mehr angefasst; es wird nur noch einmal scharf gestellt und sofort wieder an den Dauerautofokus abgegeben.",
  "<b>Der eingebaute Barcode-Leser des Geräts liest mit.</b> Wo es ihn gibt (Android/Chrome), benutzt die App jetzt zusätzlich dieselbe Erkennung, die native Scanner-Apps verwenden – sie läuft ausserhalb der App, ist schneller und kommt mit unschärferen und schrägen Codes zurecht. Beide Leser schauen auf dasselbe laufende Bild, wer zuerst einen Code sieht, gewinnt. Auf Geräten ohne diesen Leser bleibt alles wie in 3.220."],
 "3.222":["<b>Kamerawahl und Zoom im Scanner.</b> Gemeldet zu 3.221: der Code wird nicht scharf und nicht erkannt, während eine native Scanner-App auf demselben Gerät in einer halben Sekunde liest. Der Grund liegt am Fokus, nicht an der Erkennung: ein Handy hat hinten mehrere Kameras, und die Ultraweitwinkel-Kamera hat einen <i>festen</i> Fokus – näher als etwa 10 cm wird sie grundsätzlich nicht scharf. Welche Kamera der Browser nimmt, entscheidet bisher er allein. Jetzt steht unter dem Bild eine Kamerawahl: durchprobieren, die Wahl wird gemerkt.",
  "<b>Dazu ein Zoom-Regler</b>, wo das Gerät Zoom kann. Der verlässlichste Weg im Browser ist nicht, näher heranzugehen, sondern aus 20–30 cm zu zoomen – dort wird jede Kamera scharf. Auch der Zoom wird gemerkt.",
  "<b>Und: „Technische Angaben zur Kamera“</b> ganz unten im Scanner. Dort steht, was das Gerät wirklich liefert – welche Kameras es gibt, welche läuft, mit welcher Auflösung, was sie beim Fokus und beim Zoom kann, ob der eingebaute Barcode-Leser da ist und wie viele Leseversuche laufen. Die Angaben lassen sich kopieren und weitergeben. Bei einem Kameraproblem muss damit nicht mehr geraten werden."],
 "3.223":["<b>Behoben: aus der Kamera kam man nicht zurück, ohne die App zu schliessen.</b> Der Scanner war als einziger Schirm nicht beim Zurück-Mechanismus angemeldet – für den gab es ihn gar nicht, also verliess die Zurück-Taste die Seite. Jetzt verhält er sich wie jeder andere Schirm: Zurück schliesst die Kamera und bringt dich zurück. Oben links steht zusätzlich „‹ Zurück“ statt „Abbrechen“ rechts. Die Kamera wird dabei richtig abgeschaltet.",
  "<b>Die Lagerverwaltung beginnt zugeklappt.</b> Bei über dreihundert Positionen war die offene Liste keine Übersicht, sondern eine Wand. Oben stehen die Kennzahlen, darunter die Scan-Knöpfe, dann das Suchfeld. „Alle anzeigen“ zeigt die ganze Liste; eine Suche zeigt ihre Treffer wie bisher immer.",
  "<b>Einscannen und Ausscannen sind jetzt die grossen Knöpfe</b>, allein in einer Zeile ganz oben. Alles andere – neues Material anlegen, Archiv, Alle anzeigen – ist eine graue Nebenzeile darunter. Erreichbar ist unverändert alles, nur die Gewichtung folgt jetzt dem, was täglich gebraucht wird."],
 "3.224":["<b>Behoben: Positionen ohne Produkt im Lager.</b> Gemeldet: in der Lagerverwaltung standen einzelne Positionen mit „kein Produkt erfasst“, ohne dass je jemand etwas daran gemacht hatte. Beim Umstieg auf Position→Produkt hatte eine einmalige Migration jeder damals vorhandenen Position ein Standard-Produkt gegeben – daraus wurde aber nie eine dauerhafte Regel. Alles, was danach dazukam (Katalog-Import, von Hand angelegt), blieb ohne. Jetzt sorgt die Datenbank selbst dafür, egal über welchen Weg eine Position entsteht. Die bestehenden Fälle sind nachgezogen; Bestände wurden dabei nicht angefasst.",
  "<b>Neue Kontrolle „Position ohne Produkt im Lager“.</b> Es gibt einen zweiten Weg in denselben Zustand: wer das letzte Produkt löscht und die Position behält. Das ist gewollt und wird deshalb <i>nicht</i> automatisch rückgängig gemacht – aber es steht jetzt in den Kontrollen, statt still dazustehen. Gewollt? Abhaken, dann meldet es sich nicht mehr."],
 "3.286":["<b>Keine Browser-Meldungen mehr.</b> Rückfragen, Hinweise und Eingaben der App erscheinen jetzt in der App selbst, ohne den Kopf \u201EAuf mikesch15.github.io wird Folgendes angezeigt\u201C. Gleiche Fragen, gleiche Antworten \u2013 nur das Fenster sieht anders aus. Die Zur\u00fcck-Taste des Handys bricht eine Rückfrage ab, ohne die App zu schliessen."],
 "3.285":["<b>Massaufnahmen im Projekt sind sortiert:</b> zuerst nach Status (abgeschlossene am Ende), dann nach Bezeichnung in alphabetischer Reihenfolge (\u201ETor 2\u201C vor \u201ETor 10\u201C). Massaufnahmen ohne Bezeichnung stehen am Ende ihrer Gruppe."],
 "3.284":["<b>Die Zur\u00fcck-Taste des Handys geht jetzt auch zwischen den Seiten der App zur\u00fcck.</b> Bisher schloss sie die ganze App, wenn man von Heute \u00fcber Projekte in ein Projekt (oder in dessen Register) gewechselt war \u2013 nur Fenster und Formulare wurden erkannt. Jetzt geht sie Register \u2192 Projekt \u2192 Projektliste \u2192 Heute zur\u00fcck; erst auf Heute verl\u00e4sst sie die App.","<b>Behoben:</b> Nachdem sich mehrere Fenster auf einmal geschlossen hatten, konnten die n\u00e4chsten Zur\u00fcck-Tasten wirkungslos bleiben."],
 "3.283":["<b>Massaufnahme im Projekt: ein Tipp \u00f6ffnet sie.</b> Bisher klappte der Tipp auf eine Massaufnahme das R\u00fcstblatt auf. Jetzt \u00f6ffnet er die Massaufnahme selbst; das R\u00fcstblatt klappt der Knopf \u201E\u25B8 R\u00fcstblatt\u201C unter der Zeile auf.","<b>Freigeben ohne \u00d6ffnen.</b> Ist eine Massaufnahme von dir noch nicht freigegeben (oder die Freigabe verfallen), steht in der Zeile ein Knopf \u201EFreigeben\u201C bzw. \u201EErneut freigeben\u201C \u2013 mit derselben R\u00fcckfrage wie im Formular."],
 "3.282":["<b>Alte Dachfenster-Aufnahmen werden markiert.</b> Dachfenster, die vor der Wahl \u201Egepunktet / gefalzt\u201C erfasst wurden, tragen in den Listen, in der R\u00fcstliste und in der Werkstatt den Hinweis \u201EAlter Zuschnitt\u201C \u2013 ihre gespeicherten Abwicklungen stimmen nicht mehr. Beim \u00d6ffnen ist die Ausf\u00fchrung jetzt nicht mehr still vorgew\u00e4hlt: bitte w\u00e4hlen und speichern (eine erteilte Freigabe verf\u00e4llt dabei).","<b>Diese Meldung zeigt nur noch die letzten 5 Versionen</b>, auch wenn die App l\u00e4nger nicht ge\u00f6ffnet wurde."],
 "3.281":["<b>Behoben: der Text unter \u201EDateien, Fotos und Verlauf \u00f6ffnen\u0022 nannte die Fotowand nicht mehr.</b> Beim Umbau von 3.280 hatte ich den Satz so umformuliert, dass die Fotowand \u201EAlle Fotos\u0022 darin nicht mehr vorkam \u2013 ein Pr\u00fcfstand hat es bemerkt. Jetzt steht sie wieder dort, mit dem, was man in ihr tun kann (nach Herkunft filtern, als Fotodokumentation ausdrucken). An den Fotos im Register selbst \u00e4ndert sich nichts."],
 "3.280":["<b>Alle Fotos eines Projekts stehen jetzt im Register \u201EDateien\u0022.</b> Deine Ansage: Fotos aus verschiedenen Massaufnahmen sollen in den Projektfotos zu sehen sein. Die Fotowand \u201EAlle Fotos\u0022 gab es schon, aber in der neuen Ansicht lag sie hinter dem Knopf \u201EDateien, Fotos und Verlauf \u00f6ffnen\u0022 \u2013 das Register zeigte nur hochgeladene Dateien. Jetzt stehen die Fotos oben im Register selbst, neueste zuerst, mit der Angabe, aus welcher Massaufnahme sie stammen; ein Tipp vergr\u00f6ssert. Es sind dieselben Bilder wie in der Fotowand: Fotos und Skizzen aus Massaufnahmen (auch archivierten), Ausmass, Rapporten, Offerten und Bilddateien. Bei mehr als 30 stehen zuerst die neuesten, ein Knopf zeigt alle.",
  "Falls du etwas anderes gemeint hast \u2013 zum Beispiel, dass in der Fotowand selbst Bilder fehlen \u2013 sag mir, welche, dann suche ich das."],
 "3.279":["<b>Ersetzte Skizzen und Fotos l\u00f6scht die App jetzt selbst.</b> Deine Frage nach der verwaisten Skizze hat es gezeigt: wer eine Skizze bearbeitet und erneut speichert, lud bisher eine neue Datei hoch, und die alte blieb liegen. Jetzt wird die ersetzte oder im Formular entfernte Datei beim Speichern gel\u00f6scht. <b>Sicherungen:</b> erst nachdem das Speichern gelungen ist (scheitert es, bleibt alles, wie es war); nur Dateien aus dem eigenen Ordner dieser Massaufnahme; nie eine Datei, auf die eine andere Massaufnahme des Projekts noch zeigt; und scheitert das L\u00f6schen oder die Pr\u00fcfung, wird nichts gel\u00f6scht und das Speichern bleibt trotzdem heil.",
  "<b>Nicht ber\u00fchrt:</b> was vor diesem Stand liegen blieb, steht weiter in der System-Administration unter \u201EVerwaiste Dateien\u0022. Und wird eine ganze Massaufnahme gel\u00f6scht, bleiben ihre Dateien weiter liegen \u2013 das war nicht gefragt."],
 "3.278":["<b>Archivierte Massaufnahmen erscheinen nicht mehr in der Suche.</b> Gefiltert wird in der Abfrage selbst, nicht erst danach \u2013 archivierte verdr\u00e4ngen also keine aktiven Treffer aus den ersten 30. Das gilt f\u00fcr die Suche nach dem Titel und f\u00fcr die Suche \u00fcber eine Projektadresse. \u201EAlle Massaufnahmen\u0022 und die Ausmass-Auswahl zeigen weiter alle."],
 "3.277":["<b>Die Hilfe kennt jetzt das Archivieren von Massaufnahmen.</b> Unter <i>Massaufnahmen im Projekt</i> steht, wie die R\u00fcckfrage nach dem Abschliessen, <i>Archivierte anzeigen</i>, <i>Reaktivieren</i> und <i>Archivieren</i> funktionieren und dass Bedarf, Zuschnitt und R\u00fcstliste weiter alle Massaufnahmen z\u00e4hlen. Das h\u00e4tte schon zu 3.276 geh\u00f6rt; die Ver\u00e4nderung in der App selbst ist dieselbe wie dort."],
 "3.276":["<b>Abgeschlossene Massaufnahmen lassen sich archivieren</b> \u2013 gleiche Prozedur wie beim Projekt. Nach dem <i>Abschliessen</i> kommt eine kurze R\u00fcckfrage; mit <i>OK</i> wird die Massaufnahme archiviert, mit <i>Abbrechen</i> bleibt sie abgeschlossen und aktiv. Im Projekt stehen aktive und archivierte Massaufnahmen getrennt: ein Knopf <i>Archivierte anzeigen (n)</i> wechselt hin und zur\u00fcck, an archivierten steht <i>Reaktivieren</i>. An jeder abgeschlossenen Massaufnahme steht zudem <i>Archivieren</i> \u2013 auch f\u00fcr die, die schon vorher abgeschlossen waren. Die Zahl im Projektkopf z\u00e4hlt die aktiven.",
  "<b>Was nicht ausgeblendet wird:</b> Material-Bedarf, Zuschnitt, R\u00fcstliste und Fotowand rechnen weiter \u00fcber alle Massaufnahmen des Projekts, auch die archivierten. Die schon abgeschlossenen Massaufnahmen wurden <b>nicht</b> von selbst archiviert \u2013 das entscheidest du je Massaufnahme."],
 "3.275":["<b>Ein Projekt auf \u201EAbgeschlossen\u0022 setzen fragt jetzt, ob es archiviert werden soll</b> \u2013 deine Ansage. Direkt nach dem Setzen kommt eine kurze R\u00fcckfrage; mit <i>OK</i> wird das Projekt archiviert (es verschwindet aus der Projektliste und steht unter \u201EArchiv und Filter\u0022, dort l\u00e4sst es sich reaktivieren), mit <i>Abbrechen</i> bleibt es abgeschlossen und aktiv. Die Frage kommt nur beim Wechsel auf \u201EAbgeschlossen\u0022 \u2013 nicht bei den anderen Status und nicht bei einem schon archivierten Projekt. Archiviert wird nie ohne deine Best\u00e4tigung."],
 "3.274":["<b>Verwaiste Dateien lassen sich ansehen.</b> In der System-Administration hat jede Zeile der Liste einen Knopf <i>Ansehen</i>: Bilder erscheinen direkt unter der Zeile, PDF und Tabellen als Link zum \u00d6ffnen. Bisher standen dort nur Pfade \u2013 man konnte nicht beurteilen, ob eine Datei weg darf. Der Link gilt f\u00fcnf Minuten, und ausgestellt wird er nur f\u00fcr eine Datei, die der Server selbst als verwaist kennt (gleiche Pr\u00fcfung wie beim L\u00f6schen). Das Ansehen l\u00e4uft \u00fcber eine eigene, rein lesende Funktion; das L\u00f6schen ist unber\u00fchrt.",
  "<b>\u201eArchiv und Filter\u0022 hat jetzt die neue Ansicht.</b> Deine Meldung: dort stand noch die alte. Die Projekte erscheinen als dieselben Zeilen wie auf der Projektseite (Titel, Zusatz, Statusmarke) \u2013 ein Tipp \u00f6ffnet das Projekt; Bearbeiten, Archivieren und L\u00f6schen stehen klein darunter. Suchfeld, Archiv-Knopf und Filter sehen aus wie dort, die Filter stehen in je einer wischbaren Zeile statt in vier umbrochenen, und der Erkl\u00e4rsatz oben ist weg. Funktionen unver\u00e4ndert; ein wartendes Projekt bietet weiter weder \u00d6ffnen noch L\u00f6schen."],
 "3.273":["<b>Dachfenstereinfassung mit separaten Seitenteilen: jetzt zwei Seitenteile je Seite</b> \u2013 nach deiner Ansage. Das <i>vordere</i> ist Mass G lang (gefalzt zus\u00e4tzlich C + B, wie das durchgehende), das <i>mittlere</i> ist einfach Mass I. Beide sind gleich breit. Vorderteil, Hinterteil und Seitenteil hinten bleiben, wie sie sind. Es sind damit acht Zuschnitte; \u201emit Knick\u0022 hat weiter sechs. Zwischen v3.270 und v3.272 hat die App bei \u201eseparat\u0022 f\u00e4lschlich die Summe G + I \u2212 H als ein einziges Seitenteil gerechnet.",
  "Das Mass H (\u00dcberlappung) \u00e4ndert keines der beiden Seitenteile \u2013 sie steckt in G und I. Beim Seitenteil gefalzt bleibt das \u201e+10\u0022 das Mass B (Umschlag am Anreiff)."],
 "3.272":["<b>Dachfenstereinfassung: zwei Zugaben richtiggestellt</b> \u2013 nach deiner Klarstellung. <b>Gefalzt:</b> das Vorderteil ist Breite vorne + 10 mm, eine Standard-Falzzugabe (bisher rechnete die App dort mit dem Umschlag am Anreiff \u2013 im Beispiel dieselbe Zahl, bei anderen Massen nicht). <b>Gepunktet:</b> das Seitenteil hinten ist N + 15 mm, eine Standard-Naht\u00fcberlappung (bisher stand dort die Abdeckkappe oben). Gefalzt bleibt beim Seitenteil hinten der Umschlag am Aufbug (T). Mit Nord Nr.1 \u00e4ndert sich keine Zahl; sie weichen erst bei anderen Massen ab."],
 "3.271":["<b>Dachfenstereinfassung: Bauart und Ausf\u00fchrung sind jetzt zwei Pflicht-Dropdowns</b> statt vier Kn\u00f6pfen \u2013 deine Ansage. <i>Bauart des Seitenteils</i> (separat / mit Knick) und <i>Ausf\u00fchrung</i> (gepunktet / gefalzt) beginnen leer; ohne Wahl l\u00e4sst sich das Register nicht verlassen und die Aufnahme nicht speichern. Gespeicherte Aufnahmen behalten ihre Wahl (\u00e4ltere gelten als separat und gepunktet).",
  "<b>Im Schnitt steht N jetzt auf der H\u00f6he von R.</b> N endet dort, wo R beginnt; die beiden liegen in einer Reihe mit C. Ist N so breit, dass die Zahl von R in sein Mass reichen w\u00fcrde, bleibt es bei eigenen Reihen \u2013 es wird nichts \u00fcbereinandergelegt.",
  "<b>Im PDF entf\u00e4llt die Tabelle \u201eSt\u00fcckliste\u0022</b> bei der Dachfenstereinfassung \u2013 sie war dasselbe wie der Zuschnitt aus Rollenblech. Die Tabelle <i>Bleilappen</i> bleibt. Ist noch kein Rollenblech-Zuschnitt vorhanden (nie eine Rolle gew\u00e4hlt), steht die St\u00fcckliste weiter da, damit das Blatt nicht ohne Zuschnittmasse bleibt."],
 "3.270":["<b>Dachfenstereinfassung: Wahl zwischen gepunktet und gefalzt</b> \u2013 im Register <i>Fenstermasse</i>, direkt unter der Bauart des Seitenteils. <b>Gepunktet:</b> die Seitenteile werden seitlich an Vorder- und Hinterteil angepunktet (die beiden reichen deshalb seitlich ins Fenster hinaus und sind gleich lang). <b>Gefalzt:</b> senkrechter Falz, die Seitenteile laufen durch. Die Wahl l\u00e4sst sich auch bei einer <b>schon gespeicherten Aufnahme</b> noch \u00e4ndern; die Zuschnitte rechnen sich beim n\u00e4chsten Speichern neu.",
  "<b>Die Abwicklungen sind neu gerechnet</b> \u2013 nach deinem Blatt \u201eNord Nr.1\u0022. Es sind jetzt sechs Zuschnitte: Vorderteil, Hinterteil und je Seite ein <b>Seitenteil</b> und ein <b>Seitenteil hinten</b>; die Teilung am Knick und die 10 mm hinten gibt es nicht mehr. Das gilt f\u00fcr beide Bauarten (separat und mit Knick). Mit deinen Massen: gepunktet 280\u00d7774, 467\u00d7774, 190\u00d7990 und 224\u00d7175; gefalzt 280\u00d7564, 467\u00d7595, 190\u00d71225 und 224\u00d7505.",
  "<b>Was sich in der Rechnung ge\u00e4ndert hat:</b> das Vorderteil rechnet ohne den Anreiff selbst (er steckt in C) und ohne die Aufbordungsh\u00f6he der Seite; das Seitenteil nimmt die Aufbordungsh\u00f6he <i>vorne</i> statt des gr\u00f6sseren Masses; das Seitenteil hinten wird aus Breite vorne und hinten berechnet. <b>Bestehende Aufnahmen</b> behalten ihre gespeicherten Zahlen, bis du sie \u00f6ffnest und neu speicherst \u2013 sie gelten als gepunktet."],
 "3.269":["<b>Behoben: im PDF der Dachfenstereinfassung stand \u201eAufbordungsh\u00f6he vorne / hinten 0 mm\u0022</b>, obwohl die Zeichnung F = 80 und Q = 95 zeigte und die St\u00fcckliste damit rechnete. Der Ausdruck las die Zahl noch in der alten Form \u201elinks / rechts\u0022. Gesehen an deinem Blatt \u201eNord Nr.1\u0022. Gerechnet wurde immer richtig \u2013 nur die Anzeige war falsch.",
  "<b>Und: die Fussnote zu den Bleilappen sagte \u201eaufgerundet\u0022</b> \u2013 es wird seit 3.262 abgerundet. Falsch war sie im PDF von Dachfenster und Kamin, in der App-Anzeige und in der Hilfe. Jetzt \u00fcberall \u201eabgerundet\u0022; die Hilfe nennt beim Dachfenster auch die Rechnung (Vorderteil C + Seitenl\u00e4nge, Hinterteil N + R)."],
 "3.268":["<b>Der Begriff hei\u00dft jetzt \u00fcberall \u201eAnreiff\u0022</b> \u2013 deine Ansage. Bei der Einfassung rund stand in der Zeichnung, in der Hilfe, in der Anleitung und in den Meldungen der Tablett-Abwicklung bisher \u201eAnreiss\u0022; die Dachfenstereinfassung schrieb schon immer \u201eAnreiff\u0022. Jetzt ist es in der ganzen App dasselbe Wort."],
 "3.267":["<b>Im Schnitt der Einfassung rund stehen jetzt der Winkel und der Lattenabstand</b> \u2013 deine Ansage. Der Winkel Dach/Rohr ist als Bogen am Rohr eingezeichnet und beschriftet, der Lattenabstand steht oben links. Beides geh\u00f6rt zu <i>jedem</i> Schnitt: Durchmesser und Winkel werden je Einfassung erfasst, in den Angaben des Blattes stand bisher nur der Wert der ersten.",
  "<b>Die Tabelle \u201eMasse\u0022 unter den Schnitten ist weg</b> (ebenfalls deine Ansage). Sie war doppelt \u2013 a, b und c stehen in jeder Zeichnung selbst \u2013 und bei mehreren Einfassungen zeigte sie nur die Werte der ersten. Die St\u00fcckliste je Einfassung bleibt.",
  "Nebenbei am erzeugten Blatt gesehen und behoben: die beiden Eckbeschriftungen (\u201e180\u00b0 \u00b7 Anreiss 20\u00b0\u0022 und \u201eUmschlag oben 135\u00b0\u0022) waren am Rand abgeschnitten, und in den Angaben stand w\u00f6rtlich \u201e&OSLASH; STANDROHR\u0022 statt \u201e\u00d8 Standrohr\u0022."],
 "3.266":["<b>Behoben: im Regierapport-Ausdruck standen Zählpfeile mitten in den Zahlen.</b> Deine Meldung vom PC: in den Spalten <i>Std.</i>, <i>Menge</i> und <i>Fr./E</i> zeichnete der Browser an jedem Zahlenfeld zwei kleine Pfeile zum Hoch- und Runterzählen – und druckte sie mit. Auf dem Tablet waren sie nicht zu sehen. Im Ausdruck sind sie jetzt weg; am Bildschirm bleiben sie, dort gehören sie hin.",
  "Dieselbe Stelle wie früher beim Datumswähler und beim Anfasser der Textfelder: das Ausblenden am Feld selbst erreicht diese Pfeile nicht, sie sind ein eigenes Element im Browser und brauchen ihre eigene Regel."],
 "3.265":["<b>Im PDF der Einfassung rund stehen jetzt ALLE Schnitte</b> – deine Ansage. Bisher war genau einer drin: der Datensatz führt die erste Einfassung zusätzlich obenauf, und nur die wurde gezeichnet. Bei mehreren Einfassungen fehlten die übrigen im Ausdruck ganz.",
  "<b>Vier Schnitte je A4-Seite</b>, zwei nebeneinander und zwei darunter, jeder mit Bezeichnung und Ø. Passt eine Vierergruppe nicht mehr auf die laufende Seite, wandert sie geschlossen auf die nächste – sie wird nicht mitten durchgeschnitten.",
  "Bei nur einer Einfassung bleibt alles wie bisher: ein Schnitt, ohne zusätzlichen Titel."],
 "3.264":["<b>Behoben: bei der Einfassung rund blieb der Zuschnitt oben rechts auf der Karte stehen.</b> Deine Meldung: bei Einfassung 1 stand ein Wert, bei Einfassung 2 nur „0 × 38 mm\u0022. <b>Gerechnet wurde immer richtig</b> – auch in Stückliste, Zuschnitt und PDF. Nur die Kartenüberschrift wurde beim Tippen nicht erneuert: sie stand noch so da, wie die Karte beim Anlegen aussah, also leer. Die erste Karte sah nur deshalb richtig aus, weil sie zuletzt mit ihren Werten gezeichnet worden war. Jetzt laufen Bezeichnung und L × B beim Eintippen mit."],
 "3.263":["<b>Behoben: eine mit Knick erfasste Dachfenstereinfassung liess sich nicht mehr speichern.</b> Beim Öffnen kam sie als „zwei separate Seitenteile\u0022 zurück – die Bauart wurde zwar gespeichert, aber nicht wieder eingelesen. Dadurch verlangte die Kontrolle Mass I, das es beim durchgehenden Seitenteil gar nicht gibt, und das Speichern brach mit „Mass I … fehlt\u0022 ab. Der Fehler kam mit 3.260 herein; jede Aufnahme bleibt jetzt in der Bauart, in der sie erfasst wurde.",
  "<b>Und: jede Meldung steht nur noch einmal da.</b> Bei nicht getrennten Seiten wurden trotzdem links und rechts geprüft – deshalb erschien jeder Hinweis doppelt.",
  "<b>Bleilappen bei Kamin und Anschlussblech werden jetzt ebenfalls abgerundet</b> (deine Ansage). Damit rechnen alle vier Arten gleich. Das ändert bestehende Zahlen: im geprüften Kamin-Fall 8 → 4, beim Anschlussblech 20 → 19."],
 "3.262":["<b>Behoben: die Anzahl Bleilappen beim Dachfenster.</b> Deine Meldung: 990 mm Seitenlänge bei 355 mm Lattenabstand ergab 6, es sollten 8 sein. Gerechnet wurde je Zuschnittstück und aufgerundet – damit zählte die Teilung am Knick mit und die Lattung wurde verfehlt. Jetzt wird gerechnet, wie du es beschrieben hast: <b>Vorderteil</b> (Mass C + Seitenlänge) und <b>Hinterteil</b> (Mass N + R), beide <b>abgerundet</b>, mal zwei für links und rechts. Dein Fall: vorne 1’215 → 3, hinten 455 → 1, je Seite 4, gesamt 8.",
  "Die Bleilappen-Tabelle auf dem Rüstblatt zeigt entsprechend vier Zeilen – Vorder- und Hinterteil je Seite – statt der bisherigen Zuschnittstücke.",
  "<b>Dazu: der Lattenabstand steht jetzt im PDF.</b> Bei Dachfenster- und Kamineinfassung stand er bisher nur als Fussnote unter der Bleilappen-Tabelle – und die fällt ganz weg, wenn die Bleilappen nicht berechenbar sind. Dann stand er nirgends. Er hat jetzt eine eigene Zeile in den Angaben, wie bei der Einfassung rund."],
 "3.261":["<b>Behoben: die Wahl „mit oder ohne Knick\u0022 war nicht zu sehen.</b> Deine Meldung. Die beiden Knöpfe standen seit 3.260 oben im Register <i>Fenstermasse</i> – nur sah man dem gewählten nichts an: beide waren grau. Zwei gleich aussehende graue Knöpfe liest niemand als Wahl. Der gewählte ist jetzt blau. Dieselbe Stelle steckte auch in <i>Linke Seite / Rechte Seite</i> bei Dachfenster und Kamin – dort war die Seitenwahl aus demselben Grund nicht abzulesen.",
  "<b>Kurze Masse werden nicht mehr von ihrer eigenen Masslinie durchstrichen.</b> Ist ein Mass kürzer als seine Zahl – „D = 42\u0022 über 17 Bildpunkten, die Zahl braucht 50 – stand die Zahl bisher trotzdem mittig und ragte beidseitig über die Pfeile hinaus. Jetzt rückt sie daneben, und zwar nach innen, weg von Kanten und Aufbügen. Das gilt für <b>alle Massaufnahme-Arten</b>, nicht nur die Dachfenstereinfassung – gezeichnet wird überall mit denselben zwei Bausteinen.",
  "Gemessen an der Dachfenstereinfassung: vorher wurden sechs Zahlen von Linien durchschnitten (M, H, C, D, F, Q), jetzt keine."],
 "3.260":["<b>Der Schnitt der Dachfenstereinfassung ist aufgeräumt.</b> Deine Meldung: man sieht nicht sofort, welches Mass für welche Länge steht, Masse überschneiden sich und stehen in der Zeichnung drin. Jetzt steht <i>kein</i> Mass mehr im Schnitt – alle liegen in Bahnen darüber und darunter, und welches Mass in welche Bahn kommt, rechnet die Zeichnung aus, statt dass es fest eingetragen wäre. Die Zeichnung ist dafür grösser geworden.",
  "<b>Warum es überhaupt schieflief:</b> die Abstände zwischen den Masszeilen waren in Millimetern angegeben und wurden deshalb mitverkleinert. Bei einem langen Dachfenster schrumpften sie auf ein paar Bildpunkte zusammen und die Zahlen klebten aufeinander. Jetzt sind es feste Abstände auf dem Bildschirm, unabhängig von der Fenstergrösse.",
  "<b>Neu wählbar: separate Seitenteile oder durchgehend mit Knick.</b> Bei <i>durchgehend</i> gibt es nichts zu überlappen – die Überlappung und das zweite Längenmass entfallen, dafür ist das erste Längenmass die ganze Länge des Seitenteils. Aus acht Zuschnitten werden sechs. Umschalten ist gefahrlos, die eingegebenen Masse bleiben stehen. Alles, was vorher gespeichert wurde, ist unverändert eine Einfassung mit separaten Seitenteilen.",
  "<b>Behoben: die verdeckte Oberkante begann zu weit vorne.</b> Sie wurde schon ab dem Fuss der Trapezschräge gestrichelt – verdeckt ist sie aber erst dort, wo die Schräge sie wirklich kreuzt. Im geprüften Beispiel waren das 265 mm Unterschied.",
  "<b>Und auf dem Rüstblatt</b> stand bisher die Zeile „Überlappung waagr. / senkr. 0 / 0 mm\u0022 – zwei Felder, die es bei der Dachfenstereinfassung gar nicht gibt. Dort steht jetzt die Bauart des Seitenteils mit der tatsächlichen Überlappung."],
 "3.259":["<b>Behoben: fünf Prüfstände waren nach 3.258 rot.</b> Alle aus demselben Grund – sie messen Aufgaben<i>zeilen</i>, und die sind seit 3.258 zugeklappt. An der App selbst war nichts kaputt; die Prüfungen klappen jetzt vorher auf. Der Ablauf dafür steht an EINER Stelle statt fünfmal.",
  "<b>Dazu aufgeräumt, was nicht auf dem Bildschirm sichtbar ist:</b> die interne Zustandsdatei war auf 68 000 Zeichen gewachsen und wuchs mit jeder Version weiter – sie enthält jetzt den aktuellen Stand, die letzten drei Versionen und die dauerhaften Regeln, alles Ältere steht im Changelog. Und der Versionswechsel läuft über ein Werkzeug statt über elf Handgriffe."],
 "3.258":["<b>Die Aufgabenliste startet jetzt zugeklappt.</b> Deine Ansage: „drehe es um, so dad zugeklappt standart ist“. Du siehst je Projekt eine Zeile – Name, Anzahl, ob etwas dringend ist – und klappst auf, was du brauchst. „Alle aufklappen“ zeigt alles auf einmal.",
  "<b>Mitgedreht hat sich, was gemerkt wird:</b> bis 3.257 merkte sich die App das Zugeklappte, jetzt das Aufgeklappte. Anders wäre es wirkungslos – zu ist ja ohnehin alles. Die alte Liste wird dabei einmal weggeräumt: sie bedeutet das Gegenteil, und stehen gelassen hätte sie genau die Projekte geöffnet, die du zugeklappt hattest.",
  "Was du aufklappst, bleibt auf dem Gerät gemerkt, auch nach dem Neuladen. Eine neu dazukommende Baustelle ist zu, wie alle anderen auch."],
 "3.257":["<b>Die Tagesaufgaben stehen je Projekt zusammen – und lassen sich zuklappen.</b> Deine Ansage: „fasse die tagesaufgaben auf der startseite pro projekt zusammen und mach die projekte zuklappbar“. Bis 3.256 stand jede Aufgabe einzeln untereinander; wer drei Baustellen hat, musste sich selbst zusammenreimen, was zum selben Objekt gehört.",
  "Der Kopf einer Gruppe nennt <b>Projekt, Anzahl und ob etwas dringend ist</b> – genug, um zu entscheiden, ohne aufzuklappen. Ein Tipp klappt zu, dann bleibt nur diese Zeile. <b>„Alle zuklappen“</b> im Abschnittskopf macht daraus die reine Übersicht; der Zustand bleibt auf dem Gerät gemerkt, auch nach dem Neuladen.",
  "<b>Die Reihenfolge ändert sich nicht.</b> Dringendes steht weiterhin zuoberst, und ein Projekt steht dort, wo seine dringendste Aufgabe stünde – nicht alphabetisch. Das war beim Gruppieren das Heikle: hätte ich neu sortiert, wäre das Dringendste nach unten gerutscht, ohne dass es jemandem auffällt.",
  "<b>Voreingestellt ist aufgeklappt</b>, und das ist gemessen statt geraten: im Betrieb standen 7 offene Aufgaben auf 4 Projekten, im Schnitt 1,8 je Projekt. Alles zuzuklappen hätte kaum etwas verborgen und jeden Handgriff einen Tipp teurer gemacht."],
 "3.256":["<b>Nachgebessert an 3.254: die Statusnummer bei einem Fehler der Texterkennung.</b> In 3.254 habe ich sie ganz weggelassen, sobald eine lesbare Meldung da war. Das war zu viel des Guten – gemeldet war die Schachtelung („Status 502: Status 503: {rohes JSON}“), nicht die Zahl. Ohne sie fehlt dir die Angabe, die du mir schicken kannst.",
  "Jetzt steht beides: der Satz zuerst, die Nummer als Anhang – „… Bitte in ein paar Minuten nochmals auf ‚Erkennen‘ tippen. (Status 503)“. Gefunden hat das die volle Regression, nicht ich: ein Prüfstand hält seit 3.34 fest, dass ein Serverfehler seinen Status nennt und nicht stumm bleibt."],
 "3.255":["<b>Ein Projekt lässt sich jetzt schon beim Anlegen zuteilen.</b> Deine Ansage: „beim projekt erstellen, soll auch schon ein zugeteilter mitarbeiter ausgewählt werden können“. Bis 3.254 ging das erst danach – Projekt anlegen, öffnen, Stammdaten aufklappen, ankreuzen, speichern. Jetzt steht die Liste gleich im Anlegen-Formular, unter dem Auftraggeber.",
  "Es ist <b>dieselbe</b> Liste wie in den Stammdaten, kein zweites Feld daneben: was beim Anlegen gesetzt wird, steht nachher dort und lässt sich jederzeit ändern. Mehrere Personen sind möglich, und es bleibt freiwillig – kreuzt niemand jemanden an, landet das Projekt wie bisher auf der eigenen Startseite. Der Satz unter der Liste sagt jeweils, wo es erscheint.",
  "<b>Dazu der Vorschlag vom Zählwerk</b>, den es in den Stammdaten seit 3.170 gibt: steht im Feld Auftraggeber ein Kunde, bei dem schon Projekte laufen, schlägt die App vor, wer dort sonst zugeteilt ist – zum Antippen. Angekreuzt wird nichts von selbst; derselbe Kunde heisst nicht automatisch dieselbe Person.",
  "Ohne Verbindung geht die Zuteilung mit in die Warteschlange – das Projekt wartet dann vollständig, nicht halb."],
 "3.254":["<b>Behoben: der Regierapport-Ausdruck hatte die Projektseite oben drauf.</b> Gemeldet mit Bildschirmfoto: über dem Rapport standen auf Seite 1 die Register (Übersicht, Offerte, Massaufnahme …) und die Rapportliste. Der Rapport selbst war richtig.",
  "Die Ursache ist älter als sie aussieht: im Druck wurden nur <i>Kopf</i> und <i>untere Leiste</i> der Ansicht ausgeblendet, der Inhalt dazwischen nicht. Solange die App beim Öffnen des Rapports die ganze Seite versteckte, fiel das nicht auf – seit die untere Leiste überall stehen bleibt (3.162), bleibt die Seite darunter aber sichtbar. Am Bildschirm deckt der Rapport sie zu, auf Papier gibt es nichts zuzudecken. Gemessen: 108 px Projektseite vor dem Rapport. Jetzt ist der ganze Rahmen im Druck aus.",
  "<b>Und: die Fehlermeldung beim PDF-Import sagt jetzt, was los ist.</b> Gemeldet: „Fehler bei der Erkennung: Server antwortete mit Status 502: Server antwortete mit Status 503: {\"error\":{\"code\":503 …}}“ – dreimal derselbe Satzbau ineinander, zuunterst englisches JSON. Daraus liest niemand ab, was zu tun ist, und es sieht aus, als sei das eigene PDF kaputt. Es war ein Überlastungs-Engpass beim Anbieter.",
  "Jetzt steht ein Satz da: dass die Texterkennung überlastet ist, dass es <b>nicht</b> am Dokument liegt, wie oft es versucht wurde und dass das PDF hochgeladen bleibt. Der technische Rohtext ist nicht weg, er steht nur nicht mehr im Dialog. Dieselbe Regel wie seit 3.137 beim rohen Datenbanktext.",
  "<b>Dazu länger durchhalten:</b> die App versucht es bei Überlastung jetzt viermal über rund 17 Sekunden statt dreimal über 2 Sekunden – der gemeldete Engpass hat die zwei Sekunden überdauert. Bei einem echten Fehler (falsches Dokument, fehlendes Recht) wird weiterhin sofort gemeldet; dort würde Warten nichts bringen."],
 "3.253":["<b>„Materialbestand“ heisst jetzt „Material & Blech“.</b> Deine Entscheidung. Solange daneben „🏭 Lagerverwaltung“ stand, war der Name noch irgendwie einzuordnen; jetzt sagt er, was drinsteht: welche Bleche der Betrieb führt, mit Stärke, Ausführung und Rolle/Tafel.",
  "<b>Das Register darüber heisst „Blech“ statt „Lager“.</b> Darin stehen nur noch Material &amp; Blech und Reststücke – ein Register namens „Lager“, das nicht das Lager ist, wäre genau die Verwechslung zurück, die wir gerade aufgeräumt haben. Umbenannt ist nur die Beschriftung: dieselben Abschnitte, derselbe Platz, dieselben Daten.",
  "<b>Dabei gefunden: fünf Hilfetexte nannten den falschen Weg.</b> Sie schickten dich nach „Einstellungen → <i>Allgemein</i> → Materialbestand“ – dort war der Abschnitt nie, er liegt im Register daneben. Wer dem Text folgte, suchte am falschen Ort. Jetzt steht überall „Einstellungen → Blech → Material &amp; Blech“."],
 "3.252":["<b>Behoben: im Lager fehlte die untere Leiste.</b> Nachgezogen zu 3.251 – der Lager-Knopf führt jetzt ins Lieferanten-Lager, und dessen Schirm legte sich über die Leiste, mit der man hergekommen war. Vorher war dort die Lagerverwaltung, die dafür eingerichtet war. Dazu: das „‹ Zurück“ oben wusste nichts von diesem Schirm – wer ihn über seinen eigenen Knopf schloss, hatte oben einen Zurück-Knopf ohne Wirkung.",
  "Gefunden hat das die volle Regression nach dem Veröffentlichen, nicht die Schnellprüfung davor: fünf Prüfstände auf einmal. Genau dafür läuft sie hinterher."],
 "3.251":["<b>Die alte Lagerverwaltung ist abgeschafft.</b> Deine Ansage: „die altr lagerverwaltung wird abgeschafft“. Gemessen, bevor etwas wegkam: <b>1 Barcode</b> und <b>8 Buchungen</b> im ganzen Betrieb – die 381 Produkte hatte ein Trigger automatisch angelegt, nicht du. Der Knopf <b>Lager</b> in der Leiste führt jetzt direkt ins Lieferanten-Lager; den doppelten Eintrag unter „Mehr“ braucht es dadurch nicht mehr.",
  "<b>Was mitgegangen ist:</b> „📤 Material ab Lager ausbuchen“ in der Massaufnahme und die Karte „📦 Material ab Lager“ im Projekt. Du hast gesagt, du brauchst das nicht. Das Lieferanten-Lager ersetzt es nicht und soll es nicht: es führt Handelsware, kein Blech.",
  "<b>Was NICHT mitgegangen ist, obwohl es dort lag:</b> der Dialog „📦 Neue Materialposition anlegen“ samt dem begründeten Vorschlag für die EDV-Nr. Der gehörte nie zum Lager, sondern zum Material-Katalog – er ist umgezogen, nicht nachgebaut, und sieht nur noch aus wie das, was er tut: eine Position. Die Hälfte mit Barcode und Lager-Produkt ist weg.",
  "<b>Dabei gefunden: das Löschen im Material-Katalog warnte zu wenig.</b> Es fragte nur „Dieses Material wirklich löschen?“. Die ausführliche Warnung – dass bei einem Blech das <i>Format</i> mitgeht und der Zuschnitt danach nicht mehr mit diesem Blech rechnet – gab es nur auf dem Weg über die Lagerverwaltung, den fast niemand ging. Sie hängt jetzt an der Löschung selbst.",
  "<b>Und: die Kontrolle „Katalogposition, die nie vorkam“ war blind.</b> Sie galt eine Position als benutzt, sobald es ein Lagerprodukt dazu gab – und der Trigger legte zu <i>jeder</i> Position eines an. Gemessen: 760 Positionen, 760 mit Produkt, keine ohne. Sie hat also nie etwas gemeldet, und zwar nicht, weil alles in Ordnung war. Jetzt zählt, was eine Verwendung wirklich belegt: das Zählwerk und ein Reststück aus diesem Material.",
  "<b>Die Tabellen in der Datenbank bleiben vorläufig stehen.</b> Erst wenn diese Fassung eine Weile im Betrieb war, kommen sie weg – in dieser Reihenfolge, damit nichts unwiederbringlich ist, solange noch etwas auffallen kann."],
 "3.250":["<b>Behoben: die Tabelle „Wie muss die Datei aufgebaut sein?“ lief auf dem Handy aus dem Bild.</b> Gemessen bei 390 px Fensterbreite: die Tabelle <b>1000 px</b> breit in einem <b>342 px</b> Behälter – und weil weder sie noch ihr Kasten seitwärts scrollen, war die dritte Spalte unerreichbar. Also genau die mit den erlaubten Spaltenüberschriften, das Einzige, weswegen man diesen Abschnitt öffnet.",
  "Die Ursache war eine <b>richtige</b> Regel an der falschen Stelle: in der App gilt grundsätzlich, dass Tabellen mindestens 1000 px breit sind – die Stücklisten brauchen das und stehen in einem scrollenden Kasten. Drei schmale Tabellen setzen das schon seit längerem zurück; die Aufbau-Tabelle hatte den Rücksetzer nie bekommen. Behoben für <b>alle vier</b> Importe (Materialkatalog, Blitzschutz, Lieferanten-Lager).",
  "<b>Dazu grössere Trefferflächen bei den Schaltern.</b> Das Kästchen ist 13 px, getippt wird aber die ganze Zeile – die war 340 px breit und nur <b>19 px hoch</b>. Breit genug, hoch nicht: auf dem Dach mit kalten oder nassen Händen ist das fummelig. Jetzt 30 px. Nicht die 44 px aus den Mobilrichtlinien, sonst wächst die Rechtematrix unnötig in die Länge.",
  "<b>Und das wird jetzt gemessen, nicht nur behoben.</b> Die Prüfstände haben bisher geprüft, ob Bedienteile <i>da</i> sind – nicht, ob sie <i>passen</i>. Neu laufen alle fünf Lager-Dialoge bei <b>320 und 390 px</b> durch und dürfen nichts aus dem Bild schieben."],
 "3.249":["<b>„Dafür gibt es bei uns keine Regie-Position“ lässt sich jetzt festhalten.</b> Deine Ansage: die fehlenden Artikel bleiben so, es gibt dafür keine Positionen. Das kann die App nicht selbst erkennen – ob es für eine 400er Rinne bei euch eine Abrechnungsposition geben soll, weisst nur du. Ohne einen Platz dafür hätte der Knopf <b>dauerhaft „158 offen“</b> gemeldet.",
  "Und das wäre nicht bloss unschön: ein Zähler, der Arbeit anzeigt, die keine ist, <b>verdeckt die echte</b> – sobald eine neue Lieferantenliste kommt, deren Artikel sich wirklich zuordnen lassen, fällt sie zwischen 158 Dauerposten nicht mehr auf.",
  "Festhalten geht je Zeile mit einem Schalter oder für alle angezeigten mit <b>🚫 Alle angezeigten: keine Regie-Position</b> – gruppenweise, wie beim Zuordnen selbst. 158 Artikel einzeln anzutippen wäre ein Nachmittag. Zurücknehmen geht genauso.",
  "<b>Entschieden ist nicht archiviert.</b> Der Artikel bleibt im Lager voll nutzbar: Bestand, Mindestbestand, Einkaufsliste und Inventur brauchen keine Regie-Position – nur das Verrechnen im Regierapport braucht sie. Deshalb wird er <i>nicht</i> archiviert. Wie viele entschieden sind, steht oben weiterhin da; verschwiegen wird nichts.",
  "<b>Der Scanner rät nicht mehr ins Leere.</b> Bisher sagte er bei jedem Artikel ohne Position „unter 🔗 Zuordnen nachtragen – danach geht das Scannen“. Bei einem, der nie eine bekommt, ist das ein Rat ins Nichts. Jetzt sagt er stattdessen, dass sich der Artikel nicht übernehmen lässt und das Material von Hand erfasst wird.",
  "Ein Artikel <b>mit</b> Zuordnung kann die Entscheidung nicht tragen – sonst stünden zwei Wahrheiten über dieselbe Frage da. Diese Regel steht in der <b>Datenbank</b>, nicht im Formular, damit sie sich nicht umgehen lässt."],
 "3.248":["<b>Eine Passwortregel – an einer Stelle, und sie weist jetzt auch das Offensichtliche ab.</b> Supabase könnte neue Passwörter gegen geleakte Listen prüfen (HaveIBeenPwned), das ist aber ein Pro-Merkmal und steht deinem Konto nicht zur Verfügung. Die Lücke bleibt also – und „mindestens 8 Zeichen“ allein lässt <b>12345678</b> durch, seit Jahren das häufigste Passwort überhaupt.",
  "Abgewiesen wird jetzt, was als Erstes durchprobiert wird: eine <b>durchlaufende Zahlenreihe</b>, immer <b>dasselbe Zeichen</b>, die kurze Liste der geratenen Wörter („passwort“, „spengler“, „willkommen“) – und der <b>eigene Name oder Firmenname</b>, wenn danach kaum etwas übrig bleibt. „Künzi1x“ nein, „Mike-Winterdach-7“ ja. Umlaute und Gross-/Kleinschreibung helfen nicht beim Umgehen: „KÜNZI1x“ zählt gleich.",
  "<b>Sonderzeichen, Ziffern und Grossbuchstaben verlangt die App bewusst nicht.</b> Erzwungene Komplexität erzeugt „Sommer2026!“ und Zettel am Bildschirm. Was wirklich trägt, ist Länge: <b>ein paar Wörter hintereinander</b> sind leicht zu merken und schwer zu raten.",
  "<b>Und jede Ablehnung sagt, woran es liegt.</b> Nicht „ungültig“, sondern „dieses Passwort steht auf jeder Liste, die zum Durchprobieren benutzt wird“ – sonst rät man herum.",
  "Nebenbei aufgeräumt: „mindestens 8 Zeichen“ stand an <b>drei</b> Stellen als je eigene Zeile (eigenes Passwort, Zurücksetzen, Registrierung). Drei Kopien derselben Regel laufen auseinander, sobald eine erweitert wird – genau das ist hier passiert. Jetzt steht sie an einer Stelle, und die 8-Zeichen-Grenze gilt unverändert auch <b>serverseitig</b>."],
 "3.247":["<b>Das Lieferanten-Lager steht jetzt auch in der Stammdaten-Kontrolle.</b> Es ist seit 3.231 da, kam dort aber nicht vor – meine Befunde sahst du nur, wenn du den Zuordnen-Dialog öffnest. Zwei Prüfungen sind dazugekommen, und bewusst nur diese zwei: die Zustände, die man sonst <i>nicht sieht</i>.",
  "<b>Artikel auf einer Position anderer Grösse</b> (rot). Eine 400er Rinne auf der 250er Position: wird sie gescannt, steht der Preis der anderen Grösse auf der Rechnung, und auffallen würde es niemandem. Seit 3.243 setzt die App das nicht mehr von selbst – bestehende Zuordnungen sind aus der Zeit davor. Bei dir sind es <b>zwei</b>. <b>Abhakbar</b>, denn es kann fachlich gewollt sein.",
  "<b>Artikel mit negativem Bestand</b> (rot). Es wurde mehr ausgebucht als je eingebucht – meist ein Scan ohne erfassten Zugang. Der Rapport ist deswegen richtig, das Lager nicht. <b>Nicht abhakbar</b>: eine falsche Zahl bleibt falsch, behoben wird sie mit einem Zugang oder einer Korrektur. Bei dir heute: <b>keiner</b>.",
  "<b>Warum nicht mehr Prüfungen?</b> „158 Artikel ohne Regie-Position“ und „in dieser Gruppe ist noch nichts zugeordnet“ stehen schon am Knopf 🔗 Zuordnen und im Kopf der Zuordnen-Ansicht. Sie hier zu wiederholen wäre eine zweite Stelle für dieselbe Zahl – und zwei Stellen laufen irgendwann auseinander.",
  "Beide Prüfungen brauchen das <b>geladene</b> Lieferanten-Lager. Warst du noch nicht dort, fallen sie aus und <b>sagen das</b> – eine leere Liste wäre sonst die Auskunft „alles in Ordnung“, und das ist der teure Irrtum. Der Knopf <b>öffnen</b> führt direkt ins Lager."],
 "3.246":["<b>Die Einkaufsliste gehört jetzt zu EINEM Lieferanten.</b> Das war eine Unstimmigkeit in meiner eigenen Arbeit: seit 3.241 wirkt der Lieferanten-Filter in Artikelliste, Zuordnen und Inventur – in der Einkaufsliste nicht. Dabei geht eine Bestellung an <b>genau einen</b> Händler, und die <b>Summe</b> darunter rechnete quer über alle: eine Zahl, die zu keiner Bestellung gehört.",
  "Jetzt gehören Liste, Summe und der <b>verschickte Text</b> zum gewählten Lieferanten. Der Text trägt ihn im Titel („Einkaufsliste B-Team vom 1.10.2026“) und enthält den anderen nicht – er ist damit die Bestellung, nicht eine Übersicht. Ohne Wahl bleibt alles wie bisher: alle Händler, nach Lieferant gruppiert.",
  "<b>Was der Filter ausblendet, steht da:</b> „Bei anderen Lieferanten fehlen zusätzlich 4 Positionen.“ Und ist bei dem gewählten Händler nichts zu bestellen, sagt die App genau das – statt des irreführenden „nichts zu bestellen“.",
  "<b>Der Zähler am Knopf zählt weiterhin alle.</b> 📋 Einkaufsliste (7) ist das Signal „es liegt Arbeit“ und steht ausserhalb der gefilterten Ansicht. Ein Zähler, der still einen Händler unterschlägt, wäre die gefährliche Richtung: eine Bestellung, die niemand aufgibt, weil sie hinter einem Filter lag.",
  "<b>Dazu ein neuer Prüfstand, der den ganzen Lagerkreis in einem Durchgang abgeht</b> – Inventur → Mindestbestand → Einkaufsliste → Wareneingang → Scannen → Bewegungen, in einer Sitzung, mit den Zahlen an jeder Übergabe. Elf Versionen haben je ein Stück gebaut, jedes für sich geprüft; die Übergaben dazwischen waren es nicht. Ergebnis: der Kreis hält, 32 von 32."],
 "3.245":["<b>Deine Preisliste wäre nicht hereingekommen.</b> Eine Preisliste vom Händler hat zwei Spalten: <b>Artikel-Nr.</b> und <b>Preis</b>. Keine Bezeichnung. Die war im Import aber unbedingt Pflicht – und der Abgleich verwirft jede Zeile, bei der ein Pflichtfeld fehlt. Dein Upload hätte also <b>null Zeilen</b> importiert, mit der Meldung „Das Pflichtfeld Bezeichnung ist keiner Spalte zugeordnet“. Gefunden, bevor die Datei da ist: 0 von 439 Artikeln haben heute einen Preis.",
  "<b>Jetzt gilt: Pflicht ist, was eine NEUE Position braucht.</b> Eine Bezeichnung braucht, wer einen Artikel anlegt. Wer einen vorhandenen pflegt, hat sie längst in der App – und eine Spalte, die in der Datei fehlt, wird vom Import ohnehin nie geleert. Genauso läuft jetzt eine Datei nur mit <b>Mindestbestand</b> oder nur mit <b>Barcodes</b> durch.",
  "Eine Nummer, die das Lager noch <b>nicht</b> kennt, wird dabei ausgelassen und <b>gezählt</b>: „1 Zeile(n) sind noch nicht im Lager und werden ausgelassen – eine neue Position ohne Bezeichnung wäre eine Zeile ohne Namen.“ Still verschwinden lassen wäre schlimmer als auslassen.",
  "<b>Beim Materialkatalog bleibt der Name unbedingt Pflicht.</b> Die Lockerung gilt nur dort, wo sie gesetzt ist – sonst wäre die Regel still überall weicher geworden, auch wo sie gelten soll."],
 "3.244":["<b>„Was fehlt“ ist jetzt eine Arbeitsliste, nicht ein Befund.</b> v3.243 sagt dir, dass 115 Artikel nicht zuordenbar sind. Die nächste Frage ist „und was muss ich tun?“ – und die Antwort steht in <b>deiner eigenen Liste</b>. Je Zeile <b>eine Position</b>, die du anlegen könntest, nicht je Artikel: aus 158 offenen Artikeln werden damit rund drei Dutzend Zeilen.",
  "<b>Die App folgt dem Stil deiner Liste, sie rät ihn nicht.</b> Du führst beides: beim Blech je Werkstoff (201.01 Kupfer, 201.11 Titanzink, 201.13 Chromnickelstahl), beim Formteil als „alle Materialien“ (203.41 Einhängestutzen, 203.21 Rinnenboden, 203.01 Rinnenwinkel). Beim Blech ist der Werkstoff der Preis, beim Formteil nicht. Welcher Stil in einer Gruppe gilt, verraten die dort bereits zugeordneten Artikel – deshalb bekommt die 400er Titanzink-Rinne das <i>Titanzink</i>-Muster und nicht das häufigere Kupfer-Muster.",
  "Die Liste ist in <b>zwei Teile</b> geteilt, weil sie Verschiedenes bedeuten. <b>A) Vorhandene Position in anderer Grösse</b> – Name und Einheit stehen fest, es fehlen nur EDV-Nr. und Preis. <b>B) Warenart fehlt ganz</b> – Rinnenhaken eckig, Rinnenkugelböden, Schrägstutzen: das ist keine Kopie, sondern eine fachliche Entscheidung. Dazu nennt die App die ähnlichste vorhandene Position zur Orientierung.",
  "<b>EDV-Nr. und Preis schlägt die App bewusst nicht vor.</b> Eine geratene Nummer landet in deinem Nummernsystem, ein geratener Preis auf einer Rechnung. Angelegt wird in der <b>Lagerverwaltung</b> unter „neues Material anlegen“; in der Regieliste legt die App von selbst nichts an – sie liest sie nur.",
  "Der Knopf <b>zeigt</b> die Liste jetzt im Dialog und kopiert sie zusätzlich. Eine Arbeitsliste, die nur in der Zwischenablage liegt, muss man erst irgendwohin einfügen, um sie zu sehen."],
 "3.243":["<b>Die App hätte dich in einen falschen Preis laufen lassen – das ist behoben.</b> Gemessen an deinen 439 Artikeln: 63 in Grösse <b>400</b> und 46 in <b>200</b>, davon <b>kein einziger</b> zugeordnet. Der Grund ist nicht, dass du nicht dazugekommen bist: die Regieliste führt die Rinnenpositionen nur in <b>250</b> und <b>330</b>. Es gibt die Position nicht.",
  "Gefährlich war daran nicht das Offenbleiben, sondern das Gegenteil: beim Zuordnen stand für eine 400er-Rinne die 333er-Position da – mit „wie 44× in dieser Gruppe“ davor, was sich wie eine Zusage liest. <b>Ein Druck auf „Alle angezeigten setzen“ hätte 11 Artikel auf den Preis einer anderen Grösse gesetzt</b>, und im Regierapport wäre es niemandem aufgefallen.",
  "<b>Jetzt entscheidet die Grösse mit.</b> Kein automatischer Weg geht mehr über einen Grössen-Widerspruch hinweg – weder das Gruppenmuster noch „Sichere Vorschläge“ noch „Alle angezeigten setzen“. Was ausgelassen wird, <b>steht da</b>, mit Anzahl und Grund. In der Auswahl trägt so eine Zeile <b>⚠ ANDERE GRÖSSE</b>. Von Hand geht es weiterhin: es gibt Fälle, die nur du kennst.",
  "<b>Oben steht jetzt die Aufteilung:</b> wie viele der offenen Artikel zu entscheiden sind – und wie viele sich gar nicht zuordnen lassen. <b>📋 Was fehlt</b> gibt die Liste zum Mitnehmen. Ob du die Regieliste erweiterst, ist <b>deine</b> Entscheidung; die App legt dort nichts an.",
  "Zwei bereits gespeicherte Zuordnungen fragt die App nachträglich nach – 330er-Rinnen auf der 250er-Position. <b>Geändert wird nichts von selbst.</b> Und eine Dimension, die keine Grösse ist („bis 120“, „B 122“), löst nie eine Warnung aus: ein 60er-Seiher auf „bis 120“ ist richtig."],
 "3.242":["<b>Wenn Zeile und Lager auseinanderlaufen, fällt das jetzt auf.</b> Beim Scannen im Regierapport wird gebucht, was <i>gescannt</i> wurde. Änderst du die Menge in der Zeile hinterher von Hand, ändert sich die Buchung nicht – bisher stand nur in der Hilfe, dass das so ist. Jetzt steht es dort, wo es auffällt: über der Material-Tabelle. „Zeile 2 (409.373): 3 ausgebucht, die Zeile steht auf 5.“",
  "Die Meldung sagt alle drei Dinge: <b>verrechnet</b> wird, was in der Zeile steht – im <b>Lager</b> steht, was gescannt wurde – und wenn der Bestand stimmen soll, buchst du am Artikel eine <b>Korrektur</b>.",
  "<b>Automatisch nachgebucht wird nicht</b>, und das ist eine Entscheidung, kein Vergessen: hinter einer EDV-Nr. können mehrere Lieferantenartikel stehen („Rinnenseiher, alle Materialien“). „Die Zeile steht jetzt auf 5“ sagt deshalb nicht, welcher Artikel die zwei zusätzlichen Stück liefert. Eine geratene Buchung wäre schlimmer als eine sichtbare Differenz.",
  "Eine von Hand erfasste Zeile <b>ohne</b> Scan meldet nichts – sie wurde ja nie ausgebucht. Und mitgeführt wird je Artikel, nicht je Zeile; gespeichert wird es mit dem Rapport und bleibt beim Wiederöffnen erhalten."],
 "3.241":["<b>Das Lager ist jetzt auch in der Bedienung mehrlieferantenfähig.</b> Sobald mehr als ein Lieferant drin ist, erscheint oben eine <b>Übersicht</b> – je Lieferant Artikel, zugeordnet, mit Preis, mit Bestand – und ein <b>Filter</b>.",
  "Der Filter ist <b>einer</b> für alle drei Ansichten: Artikelliste, Zuordnen und Inventur. „An welchem Lieferanten arbeite ich gerade“ ist eine Frage, nicht drei. Mit nur einem Lieferanten bleiben Übersicht und Filter weg.",
  "<b>Wichtig:</b> „Alle angezeigten setzen“ greift nie über den gewählten Lieferanten hinaus – weder beim Zuordnen noch beim Mindestbestand. Und die Gruppenauswahl zeigt nur die Gruppen dieses Lieferanten.",
  "Beim Hochladen <b>warnt</b> die App, wenn der eingetippte Lieferantenname einem vorhandenen zu ähnlich ist – „bteam“ neben „B-Team“. Sonst entstünde ein zweiter Lieferant mit eigenem Nummernkreis, und auffallen würde das erst viel später. Ein Knopf übernimmt den vorhandenen Namen; geblockt wird nichts."],
 "3.240":["<b>Neu: 🧮 Inventur.</b> Ein Lager mit 439 Artikeln einzeln zu erfassen ist eine Wand – genau deshalb hatte bisher kein einziger Artikel einen Mindestbestand, und die Einkaufsliste lief leer. Die Inventur folgt dem Weg durchs Lager: Produktgruppe wählen, Regal für Regal <i>gezählt</i> eintragen und gleich daneben, wie viel immer da sein soll.",
  "<b>Setzen</b> gibt allen angezeigten Artikeln in einem Zug denselben Mindestbestand – dasselbe Prinzip wie beim Zuordnen: was du siehst, wird gesetzt.",
  "<b>Ein leeres Feld heisst „nicht gezählt“</b>, nicht „null Stück“. Nur so kannst du ein einzelnes Regal zählen und den Rest in Ruhe lassen.",
  "Eine Abweichung wird als <b>Korrektur</b> gebucht, nicht als Zugang – eine Korrektur sagt „der Bestand ist in Wirklichkeit dieser“, ein Zugang würde behaupten, Ware sei angekommen. Gebucht wird die Differenz, und in den Bewegungen steht sie mit der Herkunft <i>inventur</i>."],
 "3.239":["<b>Wareneingang: die Einkaufsliste führt sich selbst nach.</b> In der Einkaufsliste steht bei jeder Zeile ein <b>📥</b> – es öffnet den Zugang mit der <i>Bestellmenge</i> vorbelegt, also der Zahl vom Lieferschein.",
  "<b>Die Regel ist eine einzige: was da ist, fehlt nicht mehr.</b> Vollständig geliefert hakt den Einkaufswunsch ab, eine Teillieferung <i>verringert</i> ihn. Schon vor dem Buchen steht da, was passieren wird: „Offener Einkaufswunsch: 12 · danach bleiben 7 offen.“",
  "Hätte ich den Wunsch bei einer Teillieferung auf der alten Menge stehen lassen, würde die Liste weiter die ganze Menge verlangen – und beim nächsten Bestellen käme das Zuwenig doppelt.",
  "<b>Rest streichen</b> ist die Ausnahme für den Fall, dass der Rest nicht mehr kommt. Der Haken ist immer aus, solange du nichts sagst – und die <i>gewünschte</i> Menge bleibt festgehalten, damit nachvollziehbar bleibt, was verlangt war. Ein Abgang fasst den Wunsch nie an."],
 "3.238":["<b>Neu: 📜 Bewegungen im Lieferanten-Lager.</b> Jede Buchung, die neueste zuoberst – Zeitpunkt, Art, Menge, Artikel, Grund, Ziel, Projekt und wer sie gemacht hat. Filtern nach Zugang/Abgang/Korrektur, suchen nach Artikel, Projekt oder Person.",
  "<b>Der Grund:</b> seit der letzten Version bucht die App beim Scannen <i>selbst</i>. Eine Buchung, die niemand ansehen kann, ist eine Buchung, die niemand prüfen kann – hier siehst du nach, was sie getan hat.",
  "Die Liste ist <b>vollständig</b>: eine Buchung lässt sich nicht ändern und nicht löschen, ein Fehler wird mit einer Korrektur ausgeglichen. Auch eine Buchung auf einen inzwischen entfernten Artikel steht noch da – sie ist ja trotzdem passiert. Gerechnet wird hier nichts; der Bestand bleibt die Summe in der Artikelliste."],
 "3.237":["<b>Beim Scannen wird jetzt auch ausgebucht.</b> Jeder Scan im Regierapport zieht die Menge im Lieferanten-Lager ab – mit Projekt und Herkunft „Regierapport“. Erst dadurch stimmt der Bestand im Alltag: vorher hätte jemand zusätzlich von Hand ausbuchen müssen, und das passiert nie.",
  "Nach jedem Scan steht da, was gebucht wurde: <i>„1 ausgebucht, Bestand jetzt 9“</i>. Der Schalter darunter ist eingeschaltet – wer nur nachsehen will, was ein Artikel kostet, schaltet ihn aus. Die Wahl wird je Gerät gemerkt.",
  "<b>Was bewusst NICHT gebucht wird:</b> ein Artikel ohne Regie-Position (sonst wäre Ware weg, die nie verrechnet wurde) und ein Treffer aus der alten Lagerverwaltung. Beides steht dann als Hinweis da, statt verschwiegen zu werden.",
  "Ein <b>negativer Bestand</b> wird gebucht und benannt – er heisst nicht „Fehler“, sondern „hier fehlt ein Zugang im Lager“. Den Rapport daran scheitern zu lassen wäre schlimmer. Und: gebucht wird, was <i>gescannt</i> wurde, nicht was du hinterher in der Zeile änderst."],
 "3.236":["<b>Material im Regierapport scannen statt tippen.</b> Im Rapport gibt es jetzt <i>📷 Material scannen</i>: Barcode am Artikel scannen, und die Zeile trägt die passende EDV-Nr. aus eurem Katalog – mit eurem Preis. Auf dem Dach, mit Handschuhen, war das Tippen die unangenehmste Stelle.",
  "Gesucht wird im <b>Lieferanten-Lager</b> und in der <b>Lagerverwaltung</b> – ein Barcode zeigt auf eine Ware, nicht auf ein Modul. <b>Dreimal scannen heisst drei Stück:</b> derselbe Artikel am selben Tag wird hochgezählt statt doppelt angelegt.",
  "Ist ein Code nicht bekannt oder hat der Artikel noch keine Regie-Position, entsteht <b>keine Zeile</b> – und darunter steht, woran es liegt. Eine Zeile auf Verdacht wäre Material im Rapport, das niemand verbaut hat.",
  "Stand heute sind <b>281 der 439</b> Lieferantenartikel zugeordnet – und alle davon haben einen Barcode, sind also sofort scanbar."],
 "3.235":["<b>Zuordnen geht jetzt gruppenweise.</b> Oben wählst du eine <i>Produktgruppe</i> – darunter stehen nur deren Artikel. Daneben grenzt ein Suchfeld weiter ein, nach Mass („250“) oder Werkstoff („Kupfer“). So kannst du ein Grössenpaar getrennt behandeln, wenn 250 und 330 auf verschiedene Positionen gehen.",
  "<b>Alle angezeigten setzen</b> legt die ganze sichtbare Auswahl auf eine Regie-Position – EDV-Nr. tippen oder wählen, bestätigen, fertig. Was du siehst, wird gesetzt; nichts Unsichtbares.",
  "<b>Die App lernt aus deiner Entscheidung.</b> Du hast gemeldet: ein <i>Rinnenstutzen</i> ist ein <i>Einhängestutzen gerade</i>, und die App lag daneben. Am Namen kann sie das nicht erkennen – „Rinnen…“ zieht sie zu Rinnenwinkel und Rinnenboden. Jetzt gilt: ordnest du <b>einen</b> Artikel einer Gruppe von Hand zu, schlägt sie genau diese Position für alle übrigen derselben Gruppe vor („wie 40× in dieser Gruppe“). Andere Gruppen lernen davon nichts mit."],
 "3.234":["<b>Neu: die Brücke zur Regieliste.</b> Jeder Lieferantenartikel kann auf eine <b>Regie-Position</b> zeigen – die Zeile eures Katalogs, mit der er im Regierapport verrechnet wird, mit eurer EDV-Nr. und eurem Preis. Zu finden unter <i>🔗 Zuordnen</i> oder direkt am Artikel.",
  "<b>Zusammengelegt wird nichts.</b> Es sind zwei Ebenen: eure Regieliste führt „Rinnenseiher, alle Materialien“ – eine Abrechnungsposition. Der Händler führt „Rinnenseiher 60 mm“, „75 mm“ und „100 mm“ – drei Artikel. Viele Artikel zeigen auf dieselbe Position, und das ist richtig so.",
  "<b>Ein Artikel ohne passende Position bleibt ohne.</b> Nicht jeder Händlerartikel hat bei euch eine Position, und umgekehrt gibt es Regie-Positionen, die gar keine Ware sind – Rollgerüst, Elektromaschinen. Erfunden wird nichts.",
  "<b>Eure Regieliste wird dabei nur gelesen.</b> An den EDV-Nummern, den Preisen und am Regierapport ändert sich nichts."],
 "3.233":["<b>Preise im Lieferanten-Lager – schon bevor die Preisliste da ist.</b> Am Artikel gibt es jetzt ein Preisfeld. Steht einer drin, rechnet die Einkaufsliste den Zeilenwert und unten eine Summe. Kommt die Preisliste vom Händler, lädst du sie als Excel-Datei hoch – die Spalte ist schon da, es muss nichts umgebaut werden.",
  "<b>Ein fehlender Preis wird NICHT als 0 gerechnet.</b> Die Position bleibt aus der Summe draussen, und darunter steht, wie vielen Positionen der Preis fehlt. Ist überhaupt keiner hinterlegt, steht gar keine Summe da. Eine Summe, die Lücken als 0 mitnimmt, sieht vollständig aus und ist zu klein – das ist der gefährlichste Zustand.",
  "Beim Preis steht auch, <b>von wann</b> er ist. Älter als ein Jahr sagt die App ausdrücklich – ein Preis ohne Alter sieht nach vierzehn Monaten aus wie gestern."],
 "3.232":["<b>Du kannst jetzt selbst etwas auf die Einkaufsliste setzen.</b> Deine Frage war „Wo kann ich etwas in den Einkaufswagen legen?“ – die ehrliche Antwort war: nirgends. Die Liste füllte sich nur über den Mindestbestand. Jetzt tippst du im Lieferanten-Lager einen Artikel an und findest unten <i>🛒 Auf die Einkaufsliste</i>: Menge eintragen, dazuschreiben wofür („Baustelle Müller“), fertig. Ohne Mindestbestand – für die Sonderbestellung.",
  "<b>Das Symbol hat vorher gelogen.</b> Der 🛒 versprach ein Hinzufügen, das es nicht gab. Ab jetzt heisst <b>🛒 hinzufügen</b> und <b>📋 ansehen</b>: der Listen-Knopf trägt 📋 und zeigt in Klammern, wie viel draufsteht.",
  "<b>Steht ein Artikel aus beiden Gründen drauf, werden die Mengen addiert</b> – nicht die grössere genommen. Der Mindestbestand sagt, was ins Regal zurück muss, deine Handmenge, was zusätzlich auf die Baustelle geht. Beides ist echt. In der Zeile steht, woraus sich die Bestellmenge zusammensetzt, damit nichts versteckt gerechnet wird.",
  "Je Artikel gibt es genau <b>einen</b> offenen Wunsch: tippst du ihn nochmal an, kommen Menge und Grund mit und der Knopf ändert die Zeile, statt eine zweite anzulegen. Abgehakt wird in der Liste mit <b>✓</b> – das ist kein Löschen, die Zeile verschwindet nur von der Liste."],
 "3.231":["<b>Neu: die Einkaufsliste.</b> Tippe im Lieferanten-Lager einen Artikel an und trage einen <b>Mindestbestand</b> ein – die Menge, die da sein soll. Fällt der Bestand darunter, siehst du das schon in der Zeile (rot, „3 von 10“), und der Artikel steht unter <i>🛒 Einkaufsliste</i>, nach Lieferant und Produktgruppe geordnet.",
  "<b>Dort stehen zwei Zahlen, und das ist Absicht:</b> die <i>Fehlmenge</i> sagt, was fehlt – die <i>Bestellmenge</i>, was du bestellen musst. Wer 3 braucht und der Händler liefert Fünferpackungen, bestellt 5. Aufgerundet wird auf die VPE des Artikels.",
  "<b>📋 Als Text kopieren</b> gibt die ganze Liste zum Einfügen in eine E-Mail oder WhatsApp an den Händler. Erlaubt das Gerät das Kopieren nicht, steht der Text im Feld darunter – die App sagt es, statt so zu tun, als hätte es geklappt.",
  "Leer oder 0 heisst <b>nicht überwachen</b>. Sonst meldete eine Liste mit 439 Artikeln 439-mal Mangel und würde nie gelesen. Der Mindestbestand lässt sich auch in der Excel-Datei mitliefern.",
  "<b>Aus „Lager B-Team“ wird „Lieferanten-Lager“.</b> Jeder Artikel trägt jetzt seinen Lieferanten, und beim Excel-Upload wählst du oben einmal, von wem die Datei ist. Der Grund ist handfest: Artikelnummern sind nur <i>je Lieferant</i> eindeutig – eine „1001“ gibt es bei jedem Händler. Ohne diese Angabe hätte die nächste Preisliste die Artikel des ersten Händlers stillschweigend überschrieben. Deine 439 Artikel stehen unverändert da, keine Buchung war betroffen."],
 "3.230":["<b>Fehler behoben: der Excel-Upload ins Lager B-Team brach ab</b> mit einer Meldung über einen doppelten Barcode – obwohl keiner doppelt war. Ursache: 12 der 439 Artikel haben gar keinen Barcode, und eine leere Zelle galt als Wert. „Kein Barcode“ ist jetzt kein Barcode, egal wie die Zelle aussieht.",
  "Meldungen beim Excel-Import sprechen jetzt Deutsch statt Datenbank: statt „duplicate key value violates unique constraint“ steht da, was in der Datei zu bereinigen ist. Gilt auch für den Materialkatalog."],
 "3.229":["<b>Neu: Lager B-Team.</b> Ein zweites, eigenes Lager für die Handelsware des Lieferanten – Rinnen, Stutzen, Haken, Böden. Unter <i>Mehr → Lager B-Team</i>, sichtbar für alle mit Lager-Zugriff. Einscannen, ausscannen, Bestand – mit demselben Scanner wie bisher.",
  "<b>Neue Positionen lädst du als Excel- oder CSV-Datei hoch</b> – derselbe Import wie beim Materialkatalog, mit freier Spaltenzuordnung und Vorschau. Eine bekannte Artikel-Nr. wird aktualisiert, gelöscht wird nie. Das mitgelieferte Startsortiment (439 Artikel mit Barcode) steht als eigener Knopf daneben.",
  "<b>Die bestehende Lagerverwaltung und die Regiematerial-Liste sind unberührt.</b> Das neue Lager hat eigene Tabellen – euer Materialkatalog mit euren EDV-Nummern bleibt, wie er ist."],
 "3.228":["<b>Die Anleitung ist kürzer und übersichtlicher.</b> Versionsnummern in den Überschriften und Rückblicke auf frühere Fassungen sind raus – sie beschreibt jetzt nur noch, wie die App heute arbeitet. Das Inhaltsverzeichnis ist in sieben Gruppen geordnet.",
  "<b>Jeder Bildschirm der App hat seinen Info-Knopf.</b> Sieben Dialoge hatten noch keinen: Vorlage wählen, Aus Massaufnahme übernehmen, Blechverbrauch, Beispiel-Positionen und die drei der System-Administration.",
  "Fehler behoben: der Info-Knopf im Dialog „Beispiel-Positionen“ liess sich nicht vorlesen – seine Beschriftung für Screenreader fehlte."],
 "3.227":["<b>Konto wechseln gibt es nur noch für die Firmenadministration.</b> Mitarbeitende sehen den Punkt nicht mehr.",
  "<b>Der Fingerabdruck ist deshalb umgezogen</b> – er steht jetzt unter <i>Mehr → Dieses Gerät → Fingerabdruck</i> und bleibt für jeden einzeln einstellbar. Er stand bisher im Kontowechsel-Dialog und wäre dort für die Mitarbeitenden verschwunden."],
 "3.226":["<b>Fehler behoben: die Anmeldung per Fingerabdruck funktionierte nicht.</b> Beim ersten Versuch passierte nichts, und der Fingerabdruck war danach wieder ausgeschaltet. Ursache: das Abmelden macht den gespeicherten Zugang ungültig – genau den, den der Fingerabdruck wieder einsetzen wollte.",
  "<b>Der Fingerabdruck ist jetzt ein Schloss vor der App.</b> Beim Öffnen steht ein Schloss davor, Finger auflegen, drin. Daneben steht immer <i>Abmelden und mit Passwort anmelden</i>, und geht etwas schief, steht der Grund sichtbar da. Nach dem Abmelden braucht es einmal das Passwort – danach sperrt der Fingerabdruck wieder.",
  "Fehler behoben: eine Anmeldung mit dem Passwort warf den eingerichteten Fingerabdruck still weg."],
 "3.225":["<b>Anmelden mit dem Fingerabdruck.</b> App öffnen, Finger auflegen, drin – statt Benutzername und Passwort zu tippen. Einschalten unter <i>Konto wechseln</i>; der Schalter erscheint nur, wenn das Gerät wirklich einen Sensor anbietet. Der Abdruck verlässt das Gerät nie: die App bekommt vom Betriebssystem nur ein Ja oder Nein.",
  "<b>Das Passwort funktioniert weiterhin</b> und steht auf dem Anmeldebildschirm immer darunter – ein zickiger Sensor darf niemanden aus seiner eigenen App aussperren. Gilt der gespeicherte Zugang nicht mehr (Passwort geändert, lange nicht benutzt), sagt die App das und verweist aufs Passwort, statt stumm nichts zu tun.",
  "<b>Nur für ein persönliches Gerät.</b> Wer das entsperrte Gerät in der Hand hat, kommt damit ins Konto – auf einem geteilten Werkstatt-Tablet also ausgeschaltet lassen. Ehrlich dazugesagt: der Fingerabdruck ist ein <i>Schloss</i> vor dem Zugang, den die App für den Kontowechsel ohnehin schon auf dem Gerät speichert, keine Verschlüsselung. Er macht die Anmeldung damit sicherer als vorher, nicht unsicherer – vorher stand vor diesem Zugang gar nichts."],
};

// v3.282: hoechstens die neuesten 5 Versionen anzeigen, auch wenn mehr dazwischen liegen.
const WIN_MAX_VERSIONEN=5;

function winVersionVergleich(a,b){
 const pa=String(a).split(".").map(Number),pb=String(b).split(".").map(Number);
 for(let i=0;i<Math.max(pa.length,pb.length);i++){
  const x=pa[i]||0,y=pb[i]||0;
  if(x!==y)return x-y;
 }
 return 0;
}

function winAktuelleVersion(){
 const el=$("appVersion");
 if(!el)return "";
 const m=/([0-9]+\.[0-9]+)/.exec(el.textContent);
 return m?m[1]:"";
}

// Wird nach dem Login aufgerufen (js/03-login.js, afterLogin()). Zeigt die
// Kurzfassung aller WIN_CHANGELOG-Versionen zwischen der zuletzt gesehenen
// und der aktuellen Version - beim allerersten Start (noch nichts gemerkt)
// wird nichts angezeigt, nur die aktuelle Version gemerkt, damit eine neue
// Installation nicht durch die gesamte Versionsgeschichte gefuehrt wird.
function winPruefen(){
 const aktuell=winAktuelleVersion();
 if(!aktuell)return;
 let gesehen;
 try{gesehen=localStorage.getItem(WIN_LETZTE_VERSION)}catch(e){gesehen=null}
 if(gesehen===null){
  try{localStorage.setItem(WIN_LETZTE_VERSION,aktuell)}catch(e){}
  return;
 }
 if(gesehen===aktuell)return;
 const versionen=Object.keys(WIN_CHANGELOG)
  .filter(v=>winVersionVergleich(v,gesehen)>0&&winVersionVergleich(v,aktuell)<=0)
  .sort(winVersionVergleich)
  .slice(-WIN_MAX_VERSIONEN);
 try{localStorage.setItem(WIN_LETZTE_VERSION,aktuell)}catch(e){}
 if(versionen.length)winAnzeigen(versionen);
}

function winAnzeigen(versionen){
 const body=$("wasIstNeuBody");
 if(!body||!$("wasIstNeuModal"))return;
 body.innerHTML=versionen.map(v=>`<div style="margin-bottom:10px">
<div style="font-weight:800;color:var(--blue-dark)">Version ${esc(v)}</div>
<ul style="margin:4px 0 0 18px;padding:0">${WIN_CHANGELOG[v].map(z=>`<li>${esc(z)}</li>`).join("")}</ul>
</div>`).join("");
 $("wasIstNeuModal").hidden=false;
}

(function winBinden(){
 if(!$("wasIstNeuFertig"))return;
 $("wasIstNeuFertig").onclick=()=>{$("wasIstNeuModal").hidden=true};
})();
